* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * **			                  **      A P P L E   I I g s   I N S T A L L E R   P R O G R A M   V  2 . 0     **                                                                             **                              by "Jay" Schaffer                              **                               and  Ron Lichty                               **			                  **  Copyright Apple Computer, Inc. 1987-1991              All Rights Reserved  **			                  ** * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *** NOTE:  External routines, which may be located in another bank, must be sure*        they set the proper bank register values or use long addressing as*        needed.** * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	Print Push	Print Off	Include 'Installer.Equates'	include 'Installer.Records'	Print Pop	Seg 'Install'	SegAttr Dynamic	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; After compaction, the SuperScript will consist of a series of file; specification fields, each separated by the Field Separation Character.; Format of each field is as follows:;;    00-01       02-03     04-07       08-09          0A-0B	    0C-0F; [FlagsWord] [FileType] [AuxType] [CreationDate] [CreationTime] [SourceSize]; <LengthWord>[Full SourcePathname]       ¥Ê¥Ê¥ ¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥; <LengthWord>[Full DestinationPathname]  ¥ÊNOTE:StandardUpdate script uses ¥; <FieldSeparatorChar>                    ¥   partial destination pathname  ¥;		  ¥   relying on system prefix for  ¥;		  ¥   the destination volume name.  ¥; Format of the FlagWord is as follows:   ¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥Ê¥;                                              (D) (U) (F) (C) (B); _15__14__13__12__11__10__09__08__07__06__05__04__03__02__01__00_; \      /\                                  /  |   |   |   |   |;  \    /  \ - - -   R e s e r v e d  - - - /   |   |   |   |   |;   \  /                                        |   |   |   |   |;    \/   Delete if file's Creation date/time   |   |   |   |   |;    \/     is earlier than FileSpec date/time -    |   |   |   |;    \/		            |   |	|   |;    \/       Update only if destination exists ----    |	|   |;    \/		                |	|   |;    \/     FileType/AuxType must match	source file ----	|   |;    \/			|   |;    \/       Creation date/time must match source file ----    |;    \/			    |;    \/	   File is boot code for blocks 0 and 1	----;    \/;(1) 00 = INSTALL -	delete and copy, REMOVE - delete;;(2) 01 = INSTALL -	delete and copy, REMOVE - ignore;;(3) 10 = INSTALL -	delete only,     REMOVE - delete;;(4) 11 = INSTALL -	delete only,     REMOVE - ignore; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *** Equates used throughout the Install and Remove routines.** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *FlagsWord	equ $00	; Offsets to entries in FileSpecFieldFileTypeWord	equ $02AuxTypeLWord	equ $04CreationDate	equ $08CreationTime	equ $0ASourceSize	equ $0CPathnames	equ $10FieldSeparator	equ '~'	; FileSpec field separator characterCommentChar	equ '*'	; Character that designates a commentFlag1	equ %0000000000000000Flag2	equ %0100000000000000Flag3	equ %1000000000000000Flag4	equ %1100000000000000FlagB	equ %0000000000000001FlagC	equ %0000000000000010FlagF	equ %0000000000000100FlagU	equ %0000000000001000FlagD	equ %0000000000010000BootCodeSize	equ 1024; Equates associated with the header of a LoadFileByteCnt	equ $00	; Segment size (longWord)Length	equ $08	; Memory requirement (longWord)DispName	equ $28	; Offset to LoadName (Word)	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *InstallRemoveData	Proc** Description:	Data used by the Install and Remove routines.** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	Entry RemoveFlagRemoveFlag	ds.w 1	; Hi-bit set = REMOVE pressed	Entry FreeSpaceFreeSpace	ds.l 1	; Free Space on destination volume	Entry TotalBlocksForInstallTotalBlocksForInstall ds.l 1	; ThermoDial's maximum value	Entry OldMemSize	; Size of memory containing alreadyOldMemSize	ds.l 1	;  compacted scripts.	Entry ReadBufEndReadBufEnd	ds.l 1	; Address of end of	ReadBuffer	Entry ScriptSizeScriptSize	ds.l 1	; Size of individual script	Entry ScriptFlagScriptFlag	ds.w 1	; Storage for the ScriptFlag word	Entry ExecFlagExecFlag	ds.w 1	; Set if a script has actually executed; GS/OS Parameter tables	Entry OpenParms	Entry OpenSParmsOpenParmsOpenSParms	dc.w 0002	; OPEN parms for the source file	Entry OpenRefNum	Entry OpenSRefNumOpenRefNumOpenSRefNum	ds.w 1	; Reference number	Entry OpenPath	Entry OpenSPathOpenPathOpenSPath	ds.l 1	; Pathname pointer	Entry OpenDParmsOpenDParms	dc.w 0002	; OPEN parms for the destination file	Entry OpenDRefNumOpenDRefNum	ds.w 1	; Reference number	Entry OpenDPathOpenDPath	ds.l 1	; Pathname pointer	Entry ReadParmsReadParms	dc.w 0004	; pCount	Entry ReadRefNumReadRefNum	ds.w 1	; Reference number	Entry ReadBufferReadBuffer	ds.l 1	; Data buffer	Entry ReadRequestReadRequest	ds.l 1	; Request count	Entry ReadTransferReadTransfer	ds.l 1	; Transfer count	Entry CloseParmsCloseParms	dc.w 0001	; pCount	Entry CloseRefNumCloseRefNum	ds.w 1	; Reference number	Entry GetInfoParmsGetInfoParms	dc.w 0012	; pCount	Entry GetInfoPathGetInfoPath	ds.l 1	; Pathname pointer	Entry GetInfoAccessGetInfoAccess	ds.w 1	; Access	Entry GetInfoFileTypeGetInfoFileType	ds.w 1	; File type	Entry GetInfoAuxTypeGetInfoAuxType	ds.l 1	; Aux type (on file name)	ds.w 1	; Storage type	Entry GetInfoCreationGetInfoCreation	ds.l 2	; Creation date and time	ds.l 2	; Modification date	and time	dc.l 00000000	; Option List	Entry GetInfoEOFGetInfoEOF	ds.l 1	; End of file	Entry GetInfoUsedGetInfoUsed	ds.l 1	; Blocks used (total on volume name)	Entry GetInfoResEOFGetInfoResEOF	ds.l 1	; Resource end of file	Entry GetInfoResUsedGetInfoResUsed	ds.l 1	; Resource blocks used	Entry GetInfoDate1GetInfoDate1	ds.w 1	; ProDOS format creation date	Entry GetInfoTime1GetInfoTime1	ds.w 1	; ProDOS format creation time	Entry GetEOFParmsGetEOFParms	dc.w 0002	; pCount	Entry GetEOFRefNumGetEOFRefNum	ds.w 1	; Reference number	Entry GetEOFEOFGetEOFEOF	ds.l 1	; End-of-file value	Entry GetLevelParmsGetLevelParms	dc.w 0002	; pCount	dc.w 0000	; level	dc.w 0000	; level_mode	Entry ExpandPathParmsExpandPathParms	dc.w 0003	; pCount	Entry ExpandInputPathExpandInputPath	ds.l 1	; inputPath	Entry ExpandOutputPathExpandOutputPath	ds.l 1	; outputPath	dc.w 0	; not upper case	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CurFileInfo	Proc** Description:	Temporary location of the data during compaction** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	Entry ThisFlagWordThisFlagWord	ds.w 1	Entry ThisFileTypeThisFileType	ds.w 1	Entry ThisAuxFileTypeThisAuxFileType	ds.l 1	Entry ThisFileDateThisFileDate	ds.l 1	Entry ThisSrcSizeThisSrcSize	ds.l 1	Entry EndOfThisDataEndOfThisData	Entry NoMoreFileSpecsNoMoreFileSpecs	ds.w 1	Entry NumberOfFileSpecsNumberOfFileSpecs	ds.w 1	Entry ScriptParentLevelScriptParentLevel	ds.w 1	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *StandardUpdateSub	Proc Export** Description:	This is the entry point when the "Easy (Standard) Update"*	button is pressed.  It loads a special "invisible" script*	into memory, makes some determinations about the system*	disk drives and the System:Start file and then patches*	the script before executing it.** Inputs:	none** Outputs:	cFlag clear: No errors.**	cFlag set:   A-reg contains error code which has been*	             reported to the user.** External Refs:	Import Error	; From MainSub.asm*	Import MyID	; From Data.asm	Import UpdateFlag*	Import CalcAndCopy	Import CloseMsgWindow	Import Dereference	Import DoneMessage	Import InstallRemoveData ;<---¥¥¥¥¥	Import OpenInstMsgWdw	Import ReadParms	Import RestoreLevel	Import Setup	Import EliminateDuplicates	;(ELC 12/3/91)** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phb	; Preserve callers b-reg	phk	;  and set our's	plb; Load the Standard Update script into memory.BeginStdUpdate	pha	; Space for result	pha	pea rStdUpdateScript ; resourceType	pea StdUpdateScriptID>>16 ; resourceID	pea |StdUpdateScriptID	ldx #LoadResource	jsl ToolLocator	plx	ply	bcc ExecuteScript	lda #$0090	; Oops couldn't load the scriptReportError	jsl Error	pha	; Save error code	php	;  and cFlag	brl NoMsgExit; Set everything up for script execution.ExecuteScript	stx <ScriptHdl	; Store the handle	sty <ScriptHdl+2	phy	; push ScriptHdl for HLock	phx	ldx #HLock	; Lock the handle: ScriptHdl pushed previously	jsl ToolLocator	pei <ScriptHdl+2	; Dereference the handle	pei <ScriptHdl	jsl Dereference	pla	sta <ScriptPtr	pla	sta <ScriptPtr+2;       Complete the setup process.	lda #$0000	; RemoveFlag: this is an installation	jsr Setup	; Initialize variables & set level.	lda #'R'	sta ScriptFlag;       Let user know we are up to something	jsr OpenInstMsgWdw; At this point, we want to take care of any script amendments that may be; required.	jsr Amendments	; Amend as needed;       We've got to fake the DeleteField routine into thinking that;       we've read the script into the ReadBuffer.  It needs a value;       for ReadBufEnd so it can figure out how many bytes to move;       down during the field deletion operation.	pha	; Get the script's size	pha	pei <ScriptHdl+2	pei <ScriptHdl	ldx #GetHandleSize	jsl ToolLocator	clc	pla	adc <ScriptPtr	sta ReadBufEnd	pla	adc <ScriptPtr+2	sta ReadBufEnd+2; Execute the script!  Perform space calculations and copy and/or delete; files, notifying the user if anything goes wrong.	lda #$C000	; Indicate that script execution	sta >UpdateFlag	;   is in progress.;	jsr EliminateDuplicates ; removed, eliminated too much (ELC 12/12/91)		jsr CalcAndCopy	php	; save carry flag result	lda #$0000	; Indicate that script execution	sta >UpdateFlag	;   is finished; Unload the script by releasing the resource and disposing of its handle; (do not keep it around; some of its filespecs have probably been deleted).	pei <ScriptHdl+2	; Unlock the handle	pei <ScriptHdl	ldx #HUnlock	jsl ToolLocator	pea disposeNow	; purgeLevel	pea rStdUpdateScript ; resourceType	pea StdUpdateScriptID>>16 ; resourceID	pea |StdUpdateScriptID	ldx #ReleaseResource	jsl ToolLocator	plp	; get result of CalcAndCopy	bcs RestoreExit	; if carry set, abort occurred	jsr DoneMessage	; if carry clear, tell user install complete; Restore everything and exit.RestoreExit	php	; Save cFlag	pha	;  and error code, if any	jsr RestoreLevel	jsr CloseMsgWindowNoMsgExit	pla	; Restore error code, if any	plp	;  and cFlag	plb	rtl	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .Amendments	Name;; Description:	Easy Update:;	Checks the user's destination disk and the hardware;	environment to determine if the script needs amending.;	Possible amendments are to install:;;	     "Start", the SetStartup launcher file;	     "Finder", the Finderª application;	     "Finder as Start", the Finder stored as filename Start;	     "FastFonts", install and update only on devices larger than 1 meg (ELC 12/18/91);	     "UniDisk3.5", the UniDisk 3.5 driver, if it exists;	     if SCSI card exists,;	         "SCSI.Manager", the S.C.S.I. manager;	         "SCSIHD.Driver", the S.C.S.I. hard disk driver;	     if AppleShare FST exists,;	         "CDEVs:Network";	         "EasyMount";	     else if AppleTalk (ATInit) exists,;	         "SCC.Manager";	         "ATP1.ATROM";	         "ATP2.ATRAM";	         "ATResponder";; Inputs:	None;; Outputs:	cFlag clear: no errors;	cFlag set: error!  A-reg contains error code.;	Import D_TargetDevID	Import GetTargetDInfo	Import GotSCSICard	Import VolTotalBlocks  ; from MainSub.asm: CheckVolume;; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; by default, UPDATE the SetStart CDEV file (will change to INSTALL if install START)	lda #Flag2+FlagU	sta SetStartFlag; Very first thing, check to see if a SYSTEM folder exists on the; destination disk.  If not, we'll need to add the SYSTEM:START; and SYSTEM:FINDER FileSpecFields to the script or, if it's an 800K,; add the Finder under the name SYSTEM:START.	lda #SystemFolder	sta GetInfoPath	lda #^SystemFolder	sta GetInfoPath+2	jsl GSOS	dc.w Get_File_Info	dc.l GetInfoParms	bcc CheckSystemStart  ; bra if SYSTEM folder exists	cmp #FileNotFound	bne OopsError; no SYSTEM folder on destination disk: must create one; what size is the target volume: if 3.5" 800K, install Finder as START; else install SetStart	brl Update1or3; There is a SYSTEM folder.  We must check to determine what the SYSTEM:START; file "really" is.CheckSystemStart;       Open and load the first portion of the START file using partial pathname;       and the system prefix (Prefix8).OpenSystemStart	lda #SystemStart	; Setup pathname pointer	sta OpenPath	lda #^SystemStart	sta OpenPath+2	jsl GSOS	; Open the file	dc.w Open	dc.l OpenParms	bcc ReadTheFile	cmp #FileNotFound	; If the error was NOT "File Not Found"	beq jUpdateSetStart ; else no START file, so don't install Finder or StartOopsError	jsl Error	;   if NOT "File Not Found" then report errorjUpdateSetStart	brl UpdateSetStart	; don't install Finder or Start	ReadTheFile	lda OpenRefNum	; Distribute the reference number	sta ReadRefNum	sta CloseRefNum	lda #ReadBuf	; Setup the read buffer pointer	sta ReadBuffer	lda #^ReadBuf	sta ReadBuffer+2	lda #ReadBufSize	; Setup the read request to read the	sta ReadRequest	;   first $100 bytes of the file.	lda #^ReadBufSize	sta ReadRequest+2	jsl GSOS	; Read the file	dc.w Read	dc.l ReadParms	php	; Save the cFlag	pha	;   and the return code		jsl GSOS	; Close the file	dc.w Close	dc.l CloseParms	pla	; Restore the previous return code	plp	;   and cFlag	bcs OopsError;         Set up pointers, etc. so we can check the "LoadName" field of the;         LoadFile's header.CheckTheFile	ldy #DispName	; "DispName" contains offset to LoadName	clc	; Set the "<ZPTemp2" pointer to	lda ReadBuffer	;   point to the "LoadName" field.	adc ReadBuf,y	sta <ZPTemp2	lda ReadBuffer+2	adc #0000	sta <ZPTemp2+2;       Is it the Finder from early system 6.0 prototypes?  If so, and there's room, ;       replace it with the new SYSTEM:START and blindly install SYSTEM:FINDER, assuming;       it wasn't there before.	ldy #$0008	; Check all ten bytesCheckLoop1	lda [<ZPTemp2],y	cmp Finder,y	bne Check4SetStart	dey	dey	bpl CheckLoop1	bra Update1or3	; INSTALL SetStart & SetStart CDEV if there's room;       Is it the SetStart program?  If so, only UPDATE SYSTEM:FINDER!;       Since we're updating, only UPDATE SYSTEM:CDEVs:SetStartCheck4SetStart	ldy #$0008	; Check all ten bytesCheckLoop2	lda [<ZPTemp2],y	cmp SetStartFlnm,y	bne Check4Old	dey	dey	bpl CheckLoop2;       START is SetStart. Update to new one.  ;       Finder will be updated if it exists (Installer.R script has Update for Finder.)	bra UpdateStart;       If neither of the above, we need to check for older version of the;       FINDER.  We do this by looking at the "ByteCnt" and "Length" fields;       in the START LoadFiles's header and comparing against known values for;       versions 1.0, 1.1, 1.2, and 1.3 of the FINDER.Check4Old	ldy #ByteCnt	; Get ByteCnt --> A-reg	lda ReadBuf,y	;  and Length --> X-Reg	ldy #Length	ldx ReadBuf,y	cmp #$0111	; Finder V1.0 and V1.1	bne NextVersion	;   ByteCnt = $00000111	cpx #$00A6	;    Length = $000000A6	beq Update1or3	; Old Finder exists: update Finder, Start, SetStart if roomNextVersion	cmp #$E42B	; Finder V1.2	bne NextVersion01	;   ByteCnt = $0000E42B	cpx #$DF15	;    Length = $0000DF15	beq Update1or3	; Old Finder exists: update Finder, Start, SetStart if roomNextVersion01	cmp #$E5BC	; Finder V1.2 (French Version)	bne NextVersion1	;   ByteCnt = $0000E5BC	cpx #$E067	;    Length = $0000E067	beq Update1or3	; Old Finder exists: update Finder, Start, SetStart if roomNextVersion1	cmp #$025E	; Finder V1.3	bne UpdateSetStart	;   ByteCnt = $0000025E	cpx #$0215	;    Length = $00000215	bne UpdateSetStart; Old Finder exists: update Finder, Start, SetStart if room; what size is the target volume?Update1or3	lda >VolTotalBlocks+2	bne InstallSetStart ; bra if enough rm: INSTALL Start, Finder, SetStart	lda >VolTotalBlocks	cmp #2048	; 1 megabyte	bcs InstallSetStart ; bra if enough rm: INSTALL Start, Finder, SetStart; 3.5" disk: for minimum space, add Finder as START; do not install Start or SetStart	ldx #FinderAsStartSpec ; install Finder as START	ldy #^FinderAsStartSpec	jsr AmendScript	bra UpdateSetStart	; just UPDATE SetStart CDEV; 1-meg or larger (not 800K 3.5" disk) and: SYSTEM:START is an old Finder, or Start and Finder both exist.;   Install all three files (SetStart as START, SetStart CDEV, and Finder).InstallSetStart	lda #Flag2	; force INSTALL of SetStart CDEV (not just UPDATE)	sta SetStartFlag; larger than 3.5" disk and: SYSTEM:START is an old Finder, or Start and Finder both exist.;   Install both files (Start and Finder).	ldx #FinderSpec	; install the FINDER	ldy #^FinderSpec	jsr AmendScriptUpdateStart	ldx #StartSpec	; Then (or just) install the START program,	ldy #^StartSpec	jsr AmendScript; all options reconverge here: SetStart CDEV is either updated or installed depending on;   code settings from previous code testsUpdateSetStart	ldx #SetStartSpec	; Install/Update SetStart	ldy #^SetStartSpec	jsr AmendScript	Eject; Update Fast Fonts only if on volume greater than 800K (ELC1); 1st, what size is the target volume: if 3.5" 800K, delete FastFonts; else install FastFonts (ELC)	lda >VolTotalBlocks	cmp #2048	; 1 megabyte	bcc Check4UniDisk   ; bra if enough rm: INSTALL FastFontUpdateFastFont	ldx #FastFontStartSpec	; Install/Update FastFont	ldy #^FastFontStartSpec	jsr AmendScript		; UniDisk 3.5: Check for the presence of the UniDisk 3.5 driver.Check4UniDisk	lda #UniDisk	; Setup pathname pointer	sta GetInfoPath	lda #^UniDisk	sta GetInfoPath+2	jsl GSOS	dc.w Get_File_Info	dc.l GetInfoParms	bcc Check4RAM5	; cFlag clear = file exists.  Go on.;       Got an error!  Assume driver was not found!  Check to see if;       UniDisk 3.5" drive is present.; NOTE:  There is no way to identify UniDisk3.5 drives with GS/OS calls.;        SmartPort calls MUST be avoided because they ALL cause a patch;        to be executed which can cause GS/OS to lose some of its data;        structures.;;        The ONLY safe way to identify a UniDisk3.5 drive is by examining;        the SmartPort subtype entry in the Device Infomation Block (DIB).;        As long as we're doing that, we can avoid making d_Info calls as;        well to look for generic 3.5 drives since that is also contained;        in the DIB.;        The following code marches through all the DIBs looking for the;        correct Device ID Number and SmartPort subtype for positive;        identification of a UniDiskDrive.; ¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥; ¥¥¥¥¥¥¥¥¥¥ May need code to find GS/OS dPage which might change! ¥¥¥¥¥¥¥¥¥¥; ¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥DevListPointer	equ $0000BD24	; GS/OS dPage locationDevListHeaderSize	equ 4	; 4 byte headerDevListFieldSize	equ 8	; 8 byte device fieldsDevIDNumber	equ $0034	; Offset to Device ID Number in DIBGeneric3_5	equ 0003	;  Generic 3.5 Device ID NumberDevCharacteristics	equ $0008	; Offset to Device Characteristics word in DIBGeneratedDriverBit	equ $4000	;  Bit 14: 1=generated driver (no SmartPort subtype wordSmartPortSubtype	equ $0044	; Offset to SmartPort subtype in DIBUniDisk3_5	equ 0000	;  UniDisk3.5 SmartPort subtype;        The GS/OS Device List Pointer is at $00/BD24.	lda >DevListPointer	sta <ZPTemp1	lda >DevListPointer+2	sta <ZPTemp1+2;       Get the number of Device Information Blocks (DIBs) from the Device;       List Header then update <ZPTemp1 to point to the first DIB pointer.;	 __________________;       DeviceList	|_ No. of devices _|  LongWord;	|__________________|;	|_ 1st DIB pointer_|  LongWord;	|__              __|;	|_    Other data  _|  4 bytes;	|__________________|;	|                  |;	          :;	|__________________|;	|_Last DIB pointer_|  LongWord;	|__              __|;	|_    Other data  _|  4 bytes;	|__________________|	lda [<ZPTemp1]	sta NumberOfDevices	stz DeviceCounter	; Initialize our device counter	clc	; Move pointer to 1st Device field	lda <ZPTemp1	adc #DevListHeaderSize	sta <ZPTemp1	lda <ZPTemp1+2	adc #^DevListHeaderSize	sta <ZPTemp1+2;       Check all DIBs to see if any are for a UniDisk3.5UniDiskLoop	lda [<ZPTemp1]	; Get the DIB pointer into <ZPTemp2	sta <ZPTemp2	ldy #0002	lda [<ZPTemp1],y	sta <ZPTemp2+2	ldy #DevIDNumber	lda [<ZPTemp2],y	cmp #Generic3_5	; is it a 3.5 drive	bne NextDevice	;   bra if not	ldy #DevCharacteristics	lda [<ZPTemp2],y	bit #GeneratedDriverBit  ; is it a generated driver?	bne NextDevice	     ;    bra if so	ldy #SmartPortSubtype	lda [<ZPTemp2],y	cmp #UniDisk3_5	; Is it a UniDisk3.5 drive	beq InstallUniDiskDriver   ; install if soNextDevice	clc	; Move pointer to next Device field	lda <ZPTemp1	adc #DevListFieldSize	sta <ZPTemp1	lda <ZPTemp1+2	adc #^DevListFieldSize	sta <ZPTemp1+2	inc DeviceCounter	; Increment our device counter	lda DeviceCounter	cmp NumberOfDevices	;  and see if we've got them all yet.	bne UniDiskLoop	; loop	bra Check4RAM5	;   else didn't find UniDisk, so don't install driver;       Found UniDisk 3.5" drive.  Add the driver.InstallUniDiskDriver ldx #UniDiskSpec	 ldy #^UniDiskSpec	 jsr AmendScript	 Eject*** added 24-Mar-93 SSCheck4RAM5	pha	pea $37;	_ReadBParam	ldx #$0c03	jsl $e10000	pla	; if Max RAM disk then install	beq Check4SCSI	;   else didn't find RAM5, so don't install driver;       Found RAM5 drive.  Add the driver.InstallRAM5Driver	ldx #RAM5Spec	ldy #^RAM5Spec	jsr AmendScript; SCSI: Check for presence of the S.C.S.I. hard disk driver.Check4SCSI	lda #SCSIHD	; Setup pathname pointer	sta GetInfoPath	lda #^SCSIHD	sta GetInfoPath+2	jsl GSOS	dc.w Get_File_Info	dc.l GetInfoParms	bcc Check4SCSIdone	; cFlag clear = file exists.  Go on.;       Got an error!  Assume driver was not found!  Check to see if a;       S.C.S.I. card is present.	lda >GotSCSICard	; SCSI card in system?	beq Check4SCSIdone	;   bra if no SCSI card	ldx #SCSISpec	ldy #^SCSISpec	jsr AmendScriptCheck4SCSIdone; AppleShare: Check for presence of AppleShare FST.	lda #AppleShareFST	; Setup pathname pointer	sta GetInfoPath	lda #^AppleShareFST	sta GetInfoPath+2	jsl GSOS	dc.w Get_File_Info	dc.l GetInfoParms	bcs Check4AppleShareDone ; cFlag set = file doesn't exist. Do nothing.;       File exists! Install CDEVs:Network and EasyMount		ldx #AppleShareSpec	ldy #^AppleShareSpec	jsr AmendScript	bra Check4AppleTalkdone ; if AppleShare, then AppleTalk is doneCheck4AppleShareDone	; AppleTalk: Check for presence of ATInit.	lda #ATInit	; Setup pathname pointer	sta GetInfoPath	lda #^ATInit	sta GetInfoPath+2	jsl GSOS	dc.w Get_File_Info	dc.l GetInfoParms	bcs Check4AppleTalkdone ; cFlag set = file doesn't exist. Do nothing.;       File exists! Install SCC.Manager, ATP1.ATROM, ATP2.ATRAM, ATResponder	ldx #AppleTalkSpec1	ldy #^AppleTalkSpec1	jsr AmendScript	ldx #AppleTalkSpec2	ldy #^AppleTalkSpec2	jsr AmendScriptCheck4AppleTalkdoneAmendmentExit	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .AmendScript;; Description:	Amends the indicated FileSpecField to the SuperScript;	currently in memory.;; Inputs:	X and Y contain pointer to FileSpecField to add.;; Outputs:	cFlag clear: no errors.;	cFlag set: error!  Error code in A-reg.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	stx <ZPTemp2	sty <ZPTemp2+2; Begin by resizing the script's memory and setting up a pointer to the; position of the second tilde character, which marks the end of the script,; so we will overwrite it when we perform the append.	pha	; Get the size	pha	pei <ScriptHdl+2	pei <ScriptHdl	ldx #GetHandleSize	jsl ToolLocator	; Leave result on stack	pei <ScriptHdl+2	; Unlock the file	pei <ScriptHdl	ldx #HUnlock	jsl ToolLocator	clc	; Calculate new memory size	lda [<ZPTemp2]	and #$00FF	; lo byte only	adc 1,s	; add to handleSize still on the stack	tax	lda 3,s	adc #0000	cpx #0000	; Need to knock off one (we're	bne @noHiDec	;   eliminating one tilde)	dec a@noHiDec	dex	pha	; newSize	phx	pei <ScriptHdl+2	; handle	pei <ScriptHdl	ldx #SetHandleSize	jsl ToolLocator	bcc @Continue	pla	; Clean up stack	pla	lda #$0081	; Out of memory	jsl Error	bra AmendFieldExit@Continue	ldx #CompactMem	; By compacting now, we'll have	jsl ToolLocator	;  less fragmentation later	jsr GetScriptPtr	; Lock and dereference the handle	clc	; Add the former handle size to the	pla	;  new pointer to get a pointer to	adc <ScriptPtr	;  the end of the script.	tax	pla	adc <ScriptPtr+2	cpx #0000	; Subtract off one so we will	bne @noHiDec2	;  effectively delete the second	dec a	;  tilde character marking the end@noHiDec2	dex	;  of the script.	stx <ZPTemp1	; Store the pointer to the point to	sta <ZPTemp1+2	;  append the new FileSpecField.; Append the FileSpecField.  Pointer to FileSpecField is in <ZPTemp2.; Pointer to end of script is in <ZPTemp1.	lda [<ZPTemp2]	; Get FileSpecField's length byte,	and #$00FF	;  mask off extra byte, and	dec a	;  use as index.	dec a	tay	inc <ZPTemp2	; Adjust pointer to past lengthByte	bne @noHiInc	inc <ZPTemp2+2@noHiIncAppendLoop	lda [<ZPTemp2],y	; Append the field.	sta [<ZPTemp1],y	dey	dey	bpl AppendLoop	lda [<ZPTemp2]	; Be sure last byte got moved.	sta [<ZPTemp1]	clc	; Indicate no errorsAmendFieldExit	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetScriptPtr;; Description:	Locks, dereferences and stores the pointer to the;	SuperScript.;; Inputs:	none;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	lda <ScriptHdl	; If handle is null, done	ora <ScriptHdl+2	beq Done	ldy #4	; Lock the handle	lda [<ScriptHdl],y	ora #attrLocked	sta [<ScriptHdl],y	lda [<ScriptHdl]	; Dereference the handle	sta <ScriptPtr	ldy #2	lda [<ScriptHdl],y	sta <ScriptPtr+2Done	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; FileSpecFields that can be appended to the end of the StandardUpdateScript.StartSpec	dc.b StartEnd-*+1	; (A FileSpecField length byte)	dc.w Flag2	; Install	dc.w 0000	; fileType	dc.l 00000000	; auxType	dc.l 00000000	; createDateTime	dc.l 00000000	; sourceSize	dc.w SystemStart-*-2 ;sourcePathname	dc.b ':Install:System:Start'SystemStart	dc.w StartEnd-*-2	dc.b 'System:Start'StartEnd	dc.b '~~'SetStartSpec	dc.b SetStartEnd-*+1 ; (A FileSpecField length byte)SetStartFlag	dc.w Flag2+FlagU	; Install or Update (modified by code)	dc.w 0000	; fileType	dc.l 00000000	; auxType	dc.l 00000000	; createDateTime	dc.l 00000000	; sourceSize	dc.w SetStart-*-2 ;sourcePathname	dc.b ':Install:System:CDevs:SetStart'SetStart	dc.w SetStartEnd-*-2	dc.b 'System:CDevs:SetStart'SetStartEnd	dc.b '~~'FinderSpec	dc.b FinderEnd-*+1	; (A FileSpecField length byte)	dc.w Flag2	; Install	dc.w 0000	; 