EOFrwParameters		;OPEN(src)     |READ/WRITEsParameters	ds.w 1	;pCount        |pCountsRefNum		;              |rwRefNum	ds.w 1	;refNum        |refNum	sPathname		;pathname      |bufferBuffer	ds.l 1	;    "         |   "RequestCnt	ds.w 1	;requestAccess |request	ds.w 1	;resourceNumber|   "TransferCnt	ds.w 1	;access        |transfer	ds.w 1	;fileType      |   "	ds.l 1	;auxType	ds.w 1	;storageType	ds.l 2	;createDateTime	ds.l 2	;modDateTime	dc.l OptionList	;optionListsEOF	ds.l 1	;EOFOptionList	dc.w 0006,0000,0000CloseSource	dc.w 0001sourceRefNum	ds.w 1CloseDest	dc.w 0001destRefNum	ds.w 1BufferHandle	ds.l 1ReturnCode	ds.w 1	EndP ;{StandardUpdateSub}	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *InstallRemoveSubs	Proc*	Export Install	Export Remove** Description:	These are the main entry points for all Customized *	installation and removal functions.**	The Script Interpreter is called by the User Interface*	portion of the Installer program once the user has*	identified the script(s) to execute and the directory*	where Installation or Removal should take place.**	Upon entry, CurDirPtr must point to the full pathname, of*	a GS/OS Class 1 input string, of the directory where*	installation or removal should take place.  CurrentVolume*	must contain the volume name where the current directory*	is located.** Inputs:	none** Outputs:	none** External Refs:	Import CancelStr	     ; From Data.asm	Import ContinueStr	     ; From Data.asm	Import CopyProc	     ; From Data.asm	Import SpaceCalc	     ; From Data.asm	Import UpdateFlag*	Import Error	     ; From MainSub.asm	Import FlushEventQueue   ; From MainSub.asm	Import UpdateMainDialog  ; From MainSub.asm	Import Volume_Parms	     ; From MainSub.asm*	Import BuildSuperScript	Import CalcAndCopy	Import CheckForInterrupt	Import CloseMsgWindow	Import DoneMessage	Import DirSelReq	Import EliminateDuplicates	Import GetAppDirPtr	   ; From MainSub.asm	Import GetCurDirPtr	   ; From MainSub.asm	Import GStrToGStr	Import MakeNewList	Import OpenInstMsgWdw	Import RemoveFlag	Import ResizeCurDirBuf	Import UnlockCurDirHdl	Import UnlockAppDirHdl	Import RestoreLevel	Import Setup** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	Eject;=================================================; Enter here to process user request for install; (Set high bit of RemoveFlag correctly for installing)Install	lda #$0000	; RemoveFlag: this is an installation	bra StoreFlag;=================================================; Enter here to process user request for remove.; (Set high bit of RemoveFlag correctly for removing)Remove	lda #$8000	; RemoveFlag: this is a removal;=================================================; Install and Remove join again here.StoreFlag		phb	; Preserve callers b-reg	phk	;  and set ours	plb	jsr Setup	; Initialize variables, etc.	bcc BuildScript	pha	bra ScriptErrorExit2; Build the SuperScriptBuildScript	jsr OpenInstMsgWdw	; Let user know we are up to something	lda #$8000	; Indicate that a script is being read	sta >UpdateFlag; Consolidate all the selected scripts, allocate ScriptHdl	jsr BuildSuperScript	bcs ScriptErrorExit	sec	; (Don't display 'Unknown Mix" dialog)	jsr CheckForInterrupt ; Did user press OpenApple-<period>?	bcs ScriptErrorExit	jsr EliminateDuplicates ; Delete duplicate FileSpec fields	sec	; (Don't display "Unknown Mix" dialog)	jsr CheckForInterrupt ; Did user press OpenApple-<period>?	bcs ScriptErrorExitBeginCalcAndCopy	jsr CalcAndCopy	; Space calculation & copy and/or delete	bcs ScriptErrorExit; Clean up and exitScriptExit	lda #0000	; Script execution is ended.	sta >UpdateFlag	jsr GetRidOfHandle	jsr CloseMsgWindow	; Close off message window	lda >DirSelReq		bpl @1	; bra if directory selection not required	jsl GetAppDirPtr	jsl GetCurDirPtr@2	pei <AppDirPtr+2	pei <AppDirPtr	pei <CurDirPtr+2	pei <CurDirPtr	jsl GStrToGStr	; restore CurDirPtr to original value	jsl ResizeCurDirBuf	bcs @2	jsl UnlockCurDirHdl	; Let <CurDirHdl float til needed again	jsl UnlockAppDirHdl	; Let <AppDirHdl float til needed again	jsl MakeNewList	; build new folder selection list for right wdw@1; We're all finished processing the script.	bit ExecFlag	; Check to see if a script was	bpl @Exit	;  actually executed	jsl UpdateMainDialog	jsr DoneMessage@Exit	jsr RestoreLevel	jsl FlushEventQueue	plb	clc	; Everything went OK	rtl	; All done; Error exitScriptErrorExit	pha	; Save the error code	jsr GetRidOfHandle	jsr CloseMsgWindowScriptErrorExit2	jsr RestoreLevel	jsl FlushEventQueue	lda #0000	; Script execution is ended.	sta >UpdateFlag	pla	; A = error code	cmp #0001	; Notify caller of error	plb	rtl	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetRidOfHandle	; Local subroutine; ; Description:	A little local subroutine to dispose of the handle used;	for the SuperScript.;; Inputs:	none;; Outputs:	none;; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	lda <ScriptHdl+2	; Release memory containing script	pha	lda <ScriptHdl	pha	ldx #DisposeHandle	jsl ToolLocator	stz <ScriptHdl	stz <ScriptHdl+2	rts	EndP ;{InstallRemoveSub}	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *SetUp	Proc** Description:	Initializes variables and set file level.** Inputs:	A-reg: $0000 if Install pressed*	       $8000 if Remove pressed** Outputs:	cFlag clear: no errors*	cFlag set:   error!  A-reg holds error code and user has*	             been notified.** External Refs:	Import Error*	Import GetLevelParms** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	sta RemoveFlag	; Initialize variables	stz ExecFlag; Set the file level to its maximum value so that when we; do a "close-all" later, we will only close what we opened.	jsl GSOS	dc.w Get_Level	dc.l GetLevelParms	bcc @2@1	jsl Error	rts@2	jsl GSOS	dc.w Set_Level	dc.l SetLevelParms	bcs @1	rtsSetLevelParms	dc.w 0002	; pCount	dc.w $00FF	; level	dc.w $8000	; level_mode (user_level)	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *BuildSuperScript	Proc** Description:	This is the subroutine to put together a SuperScript*	from all of the user's individually selected scripts.*	It first looks for a script whose name begins with*	" System " and begins with it.  Then it appends the*	FileSpec fields from all the other scripts.** Inputs:	none** Outputs:	none*	(Allocates ScriptHdl).** External Refs:	Import CautionBtn1	    ; From Data.asm	Import CautionBtn2	    ; From Data.asm	Import DrawCautionIcon	Import LatestSys	    ; From Data.asm	Import LatestSysEnd	    ; From Data.asm	Import ScriptListCtlHdl ; From Data.asm	Import ScriptVer*	Import Allocate	    ; From MainSub.asm	Import Error	    ; From MainSub.asm*	Import CheckForInterrupt	Import CloseParms	Import CloseRefNum	Import CompactScript	Import CurScriptFile	Import GetEOFParms	Import GetEOFEOF	Import GetEOFRefNum	Import OldMemSize	Import OpenSParms	Import OpenSPath	Import OpenSRefNum	Import ReadBuffer	Import ReadParms	Import ReadRefNum	Import ReadRequest	Import ResizeScriptMemory	Import ScriptSize	Import SpaceCalc	Import UpdateMsgWindow** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	stz ScriptFlag	; init ScriptFlag to zero	stz CurrentMember; Get the first selected member.	jsr GetNextMember	beq BuildScript	sta Temp; We know we've got at least one selected item, so get an empty handle for; the memory we'll need to store the superScript.	lda #0000	jsl Allocate	stx <ScriptHdl	sty <ScriptHdl+2	stz OldMemSize	; Indicate current memory size is zero	stz OldMemSize+2	bra @Continue; Get the next selected member@SearchLoop	jsr GetNextMember	bne @StoreValue	lda #0000	bra BuildScript@StoreValue	sta Temp; Temp now contains the member's position in the list.@Continue	dec Temp	; Returned itemNum is "one" based		; We want "zero" based	lda Temp	; List has six bytes per member	asl a	;  ( X2 )\	clc	;         \	adc Temp	;  ( +1 ) /  = X6 (Record size)	asl a	;  ( X2 )/	sta Temp	ldy Temp	lda [ScriptListPtr],y	sta <ZPTemp	iny	iny	lda [ScriptListPtr],y	sta <ZPTemp+2; Check every selected member to see if any of them are a " System " file.	ldx #0000	; Initialize index	txy@CompareLoop	iny	inx	cpy #LatestSysEnd-LatestSys	beq @Match	lda [<ZPTemp],y	cmp >LatestSys-1,x	beq @CompareLoop	bra @SearchLoop	; This entry didn't match@Match	lda CurrentMember	; Begin the SuperScript with the "Latest	jsr SuperScript	; Sys" file.	bcs BuildSuperScriptEnd	sec	; (Don't display "Unknown Mix" dialog)	jsr CheckForInterrupt ; Did user press OpenApple-<period>?	bcs BuildSuperScriptEnd	lda CurrentMember; Were now ready to build (or continue building, if we already started with a; " System " file) the SuperScript.  Begin with the itemNum found in the; A-reg.  Continue calling GetNextMember skipping the value we're storing in; "LatestSysMember", below.  (If value is $FFFF, we'll get back to zero; without ever reaching it.BuildScript	sta LatestSysMember	; (Non-zero value = " System " itemNum)	stz CurrentMember	; Starting at the beginning of the list...BuildScriptLoop	jsr GetNextMember	; Get the next selected member.	sta CurrentMember	beq BuildSuperScriptExit ; If there are no more, we're donw.	cmp LatestSysMember ;   If it's the " System " item,	beq BuildScriptLoop	;     skip it.	jsr SuperScript	; Add it to the SuperScript.	bra BuildScriptLoop	; Continue til we've got them all.; Append a second trailing tilde to designate the end of the script.BuildSuperScriptExit	pha	pha	pei <ScriptHdl+2	pei <ScriptHdl	ldx #GetHandleSize	jsl ToolLocator	plx	ply;       If the memory size is more than $0000FFFF, the script is too big.	beq CheckMemorySizeScriptTooLarge	lda #$0084	; Script Too large!	jsl Error	bra BuildSuperScriptEnd;       If the memory is still zero, there is no SuperScript.  The user must;       have cancelled.CheckMemorySize	cpx #0000	bne ResizeMemory	sec	bra BuildSuperScriptEnd;       If everything is OK, append the second trailing tilde.ResizeMemory	stx Temp	inx	; Make the segment one byte larger	beq ScriptTooLarge	jsr ResizeScriptMemory	bcs BuildSuperScriptEndAppendTilde	ldy Temp	sep #$0020	LongA Off	lda #'~'	sta [<ScriptPtr],y	LongA On	rep #$0020	BuildSuperScriptEnd	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetNextMember;; Description:	Gets the next selected member in the ScriptList and;	returns it's itemNum.;; Inputs:	none;; Outputs:	A-reg contains itemNum of next selected item in ScriptList.;; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	; Room for result	lda CurrentMember	; itemNum	pha	lda >ScriptListCtlHdl+2 ; ctlHandle	pha	lda >ScriptListCtlHdl	pha	ldx #NextMember2	jsl ToolLocator	pla	sta CurrentMember	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .SuperScript;; Description:	This local subroutine displays the caution alert, if so;	directed by the header flags, and then adds the;	FileSpecFields from the specified list member onto the;	SuperScript, if the user did not cancel the script;	during the caution, if any.;; Inputs:	A-reg = itemNum of list member to add to SuperScript.;; Outputs:	c-flag clear: no errors;	c-flag set: A-reg contains error code returned by whoever;	            generated encountered the error.  User HAS;	            been notified.;; NOTES:	Each FileSpecField requires 16 bytes plus space for two;	GS/OS Class 1 input strings for FULL source and destination;	pathnames.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	sta ThisItemNum; Get some memory to read in this script	lda #0000	jsl Allocate	stx <ScriptHandle	sty <ScriptHandle+2	bcc ReadScript	lda #$0084	jsl Error	bcs SSErrorExit; Read in the script and look at the headerReadScript	lda ThisItemNum	jsr ReadWholeScriptFile	bcs SSErrorExit; Before continuing, we need to check to see if the script wants us to caution; the user before continuing.	jsr Caution	bcs SSExit; Compact and verify the script instructions, then append to the SuperScript.	lda #ScriptVer	; Keep user up to date.	jsr UpdateMsgWindow	jsr CompactScript	bcs SSErrorExitSSExit	lda #0000	clcSSErrorExit	php	pha; Finally dispose of the memory where the compacted script is.	pei <ScriptHandle+2	pei <ScriptHandle	ldx #DisposeHandle	jsl ToolLocator	lda NewMemSize	sta OldMemSize	lda NewMemSize+2	sta OldMemSize+2	pla	plp	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .ReadWholeScriptFile;; Description:	Reads the script file into memory.  Makes full pathname,;	Opens File, Gets EOF, resizes ScriptHandle, Reads file;	into handle, and Calculates ReadBufEnd.;; Inputs:	A-reg contains member's number;; Outputs:	cFlag clear: no errors;	cFlag set: error if any stored in A-reg.;* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Point the OPEN parameter to the full pathname in the ScriptFileList;;;;;;	pha	; Save the itemNum;;;;;;	pla	; Restore the itemNum;       A-reg now contains the member's position in the list.	dec a	; (We're "zero" based.)	sta Temp	; List has six bytes per member	asl a	;  ( X2 )\	clc	;         \	adc Temp	;  ( +1 ) /  = X6 (Record size)	asl a	;  ( X2 )/	tay	lda [<ScriptFilePtr],y	sta OpenSPath	sta <ScriptFilename	iny	iny	lda [<ScriptFilePtr],y	sta OpenSPath+2	sta <ScriptFilename+2; OPEN the script and determine it's size.@0	jsl GSOS	dc.w Open	dc.l OpenSParms	bcc @1	ldx OpenSPath	ldy OpenSPath+2	jsl Error	bcc @0	bra ErrorExitJJ@1	lda OpenSRefNum	sta GetEOFRefNum	sta ReadRefNum	sta CloseRefNum@2	jsl GSOS	dc.w Get_EOF	dc.l GetEOFParms	bcc @3	ldx OpenSPath	ldy OpenSPath+2	jsl Error	bcc @2	bra ErrorExitJJ@3; Check that we have not exceeded $0000FFFF, the largest script file we can handle	lda GetEOFEOF+2	; Hi-word MUST be zero!	beq ContinueScriptTooBig	lda #$0084	; Script was too big	jsl ErrorErrorExitJJ	bra ErrorExitJ; Resize script's memory to hold the scriptContinue	sta ReadRequest+2	; Store the space needed in ReadRequest	sta ScriptSize+2	;   and ScriptSize, then push on stack	pha	;   for _SetHandleSize call.	lda GetEOFEOF	sta ReadRequest	sta ScriptSize	pha	ldy #4	; Unlock the handle	lda [<ScriptHandle],y	and #$FFFF-attrLocked	sta [<ScriptHandle],y	pei <ScriptHandle+2	; Resize the memory	pei <ScriptHandle	ldx #SetHandleSize	jsl ToolLocator	bcs ScriptTooBigMemoryOK	ldy #4	; Lock the handle	lda [<ScriptHandle],y	ora #attrLocked	sta [<ScriptHandle],y	lda [<ScriptHandle]	; Dereference the handle	sta <ZPTemp	sta ReadBuffer	ldy #0002	lda [<ScriptHandle],y	sta <ZPTemp+2	sta ReadBuffer+2; READ the script into the memory@0	jsl GSOS	dc.w Read	dc.l ReadParms	bcc ReadOK	ldx OpenSPath	ldy OpenSPath+2	jsl Error	bcc @0ErrorExitJ	bra ErrorExitReadOK; CLOSE the Script file@2	jsl GSOS	dc.w Close	dc.l CloseParms	bcc @3	ldx OpenSPath	ldy OpenSPath+2	jsl Error	bcc @2	bra ErrorExit@3; We'll need to know where the end of the ReadBuffer is later.	clc	lda <ZPTemp	adc ScriptSize	sta ReadBufEnd	lda <ZPTemp+2	adc ScriptSize+2	; (always zero)	sta ReadBufEnd+2	lda #0000ErrorExit	cmp #0001	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .Caution;; Description:	This routine will check the ScriptFlagField to determine if;	the user should receive a caution before the script;	is added to the SuperScript (indicated by 2nd char being lowercase);; Inputs:	none;; Outputs:	cFlag clear if user wishes to execute the script;	cFlag set if user wishes to abort execution of the script.;; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	sep #$30	LongA Off	LongI Off		ldy #ScriptFlagField+1 ; Get the ScriptFlag; save y for @Caution	lda [<ZPTemp],y	cmp #'r'	; if lower case, display caution	beq @Caution	cmp #'n'	; if lower case, display caution	beq @Caution	LongA On	LongI On	rep #$30	clc	bra @Exit; Set up an alert box with the contents of the script's ScriptHelp field and; buttons to go ahead or abort the execution of the script.; First, find the ScriptHelp field by searching past 3 crÕs (2 after flags, 1 after name).; Still using Y from above.@Caution	LongA Off	; still 8-bit registers here	LongI Off	ldx #3	; looking for 3 crÕs (2 after flags, 1 after name)@LengthLoop	lda [<ZPTemp],y	; Y set up above	iny	cmp #Return	bne @LengthLoop	dex	bne @LengthLoop	LongA On	LongI On	rep #$30	phy	; (Save offset to ScriptHelp field)	ldx #0000	; Determine length of ScriptHelp field.@HelpLenLoop	lda [<ZPTemp],y	;   by searching for a "//" word.	iny	inx	cmp #ScriptHelpEnd	; (Check for end of ScriptHelp field)	bne @HelpLenLoop	dex	stx HelpFieldLength	clc	; Calculate beginning of Help field	pla	;   Offset to beginning of Help field	adc <ZPTemp	; + Buffer Address	sta HelpFieldPtr	lda #0	adc <ZPTemp+2	sta HelpFieldPtr+2	ldx #InitCursor	jsl ToolLocator; (Use an _Alert rather than a _CautionAlert, and define our own Caution Icon; so we can color the icon yellow.	pha	; Room for result	pea AlertTemplate>>16	pea |AlertTemplate	pea 0000	; Filter procedure	pea 0000	ldx #Alert	; Leave item hit on stack	jsl ToolLocator	ldx #WaitCursor	jsl ToolLocator	pla	; Now, get the item hit from stack	cmp #0003	; Check ItemHit ID (ID#2 < 3, carry clear, so execute)@Exit	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Caution dialog templateaWidth    equ 400aHeight   equ 104aBtnWidth equ 160aTop      equ (200/2)-(aHeight/2)aLeft     equ (640/2)-(aWidth/2)aBottom   equ aTop+aHeightaRight    equ aLeft+aWidthAlertTemplate	dc.w aTop,aLeft,aBottom,aRight	dc.w $ABCD	 ; AlertID	dc.b $81,$81,$81,$81 ; Stage1, Stage2, Stage3, Stage4	dc.l FirstItem	 ; First item template	dc.l SecondItem	 ; Second item template: Perform	dc.l ThirdItem	 ; Third item template: Skip	dc.l FourthItem	 ; Fourth item template	dc.l 00000000FirstItem	dc.w 0001		; ItemID	dc.w 5,75,aHeight-21,aWidth-20	; ItemRect	dc.w LongStatText2+ItemDisable	; ItemTypeHelpFieldPtr	dc.l 00000000		; ItemDescrHelpFieldLength	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColorSecondItem	dc.w 0002		; ItemID	dc.w aHeight-18,3*aWidth/4-(aBtnWidth/2) ;ItemRect	dc.w aHeight-6,3*aWidth/4+(aBtnWidth/2)	dc.w ButtonItem		; ItemType	dc.l CautionBtn2		; ItemDescr: ÔPerform this updateÕ	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColorThirdItem	dc.w 0003		; ItemID	dc.w aHeight-18,aWidth/4-(aBtnWidth/2)	; ItemRect	dc.w aHeight-6,aWidth/4+(aBtnWidth/2)	dc.w ButtonItem		; ItemType	dc.l CautionBtn1		; ItemDescr: ÔSkip This UpdateÕ	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColorFourthItem	dc.w 0004		; ItemID	dc.w 5,16,25,74		; ItemRect	dc.w UserItem+ItemDisable 	; ItemType	dc.l DrawCautionIcon	; ItemDescr	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColorTemp	ds.w 1OldSize	ds.l 1CurrentMember	ds.w 1ThisItemNum	ds.w 1	; itemNum of item to add to "Super"NewMemSize	ds.l 1LatestSysMember	ds.w 1	; Member with name beginning " System "	EndP ;{BuildSuperScript}	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *EliminateDuplicates	Proc** Description:	Identifies FileSpec fields in the SuperScript that deal*	with identical source and destination pathnames, resolves*	differing options and deletes one of the fields.** Inputs:	none** Outputs:	none** External Refs:	Import DeleteField1	Import ReadBufEnd	Import ResizeScriptMemory	Import UpperCase8bit* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -* NOTES:	When duplicate FileSpec fields are encountered, the first*	is the one that must be deleted since the second one may*	come from a script that took other actions first before*	handling this FileSpec for some specific reason.**	For instance, at the time this routine was implemented,*	the SCSI.Hard.Disk script deleted all the tutorial stuff*	before moving the SCSI.Manager to be sure there would be*	room.  If the SuperScript also included the CDROM script,*	it would come first and would cause the SCSI.Manager to be*	installed BEFORE the SCSI.Hard.Disk script had deleted*	the tutorial stuff, which might be needed to make room.**	Boot code replacement FileSpec must be first!  Therefore,*	it is the sole exception to the above rule.  In this case,*	the first occurrence MUST be retained and any others*	deleted!**	<ZPtemp is used as the pointer to the first FileSpec*	which is the one that will be deleted when duplicates*	are found.**	<ZPTemp1 points to the second FileSpec field.* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Start at the beginning of the SuperScript.	lda <ScriptPtr	sta <ZPTemp	sta <ZPTemp1	lda <ScriptPtr+2	sta <ZPTemp+2	sta <ZPTemp1+2; DeleteField1 uses ReadBufEnd to know how many bytes to move when it deletes; a field.  So be sure to let ReadBufEnd point to the end of our script.	clc	ldy #0008	; Get the Handle size	lda [<ScriptHdl],y	adc <ScriptPtr	sta ReadBufEnd	lda #0000	adc <ScriptPtr+2	sta ReadBufEnd+2	bra InnerLoop; This is the outer loop which updates the pointer to the first FileSpec.OuterLoop	clc	; Update <ZPTemp to point the	ldy #Pathnames	;   destination pathname first...	lda [<ZPTemp],y	;  (size of source filespec)	adc <ZPTemp	adc #Pathnames+2	;  (plus 2: length of size word)	sta <ZPTemp	lda #0000	adc <ZPTemp+2	sta <ZPTemp+2	clc	; Now update both pointers to point	lda [<ZPTemp]	;   to the byte following the field	adc <ZPTemp	;   separator character.	adc #0003	sta <ZPTemp	sta <ZPTemp1	lda #0000	adc <ZPTemp+2	sta <ZPTemp+2	sta <ZPTemp1+2;       NOTE: If the first character is a field separator character, we've;             reached the end of the script!Check4Separator	lda [<ZPTemp]	and #$00FF	cmp #FieldSeparator	bne InnerLoop	brl Exit; This is the inner loop which updates the pointer to the second FileSpec.InnerLoop	clc	; Update <ZPTemp1 to point the	ldy #Pathnames	;   destination pathname first...	lda [<ZPTemp1],y	;  (size of source filespec)	adc <ZPTemp1	adc #Pathnames+2	;  (plus 2: length of size word)	sta <ZPTemp1	lda #0000	adc <ZPTemp1+2	sta <ZPTemp1+2	clc	; Now update it to point to the byte	lda [<ZPTemp1]	;   following the field separator	adc <ZPTemp1	;   character.	adc #0003	;  (plus 3: length of size word + field sep)	sta <ZPTemp1	lda #0000	adc <ZPTemp1+2	sta <ZPTemp1+2;       NOTE: If the first character is a field separator character, we've;             reached the end of the script!Check4Separator1	lda [<ZPTemp1]	and #$00FF	cmp #FieldSeparator	beq OuterLoop; Begin comparing pathnames.  If we have a match up through and including; the FieldSeparator character both pathnames are identical.	sep #$0020	LongA Off	ldy #Pathnames-1CompareLoop	iny	lda [<ZPTemp1],y	jsl UpperCase8bit	; (Comparison must be case insensitive)	sta ElimTemp	lda [<ZPTemp],y	jsl UpperCase8bit	cmp ElimTemp	bne NoMatch	; No match	cmp #FieldSeparator	bne CompareLoop;       They match!  Resolve the options and delete one of the FileSpecFields.;       (NOTE:  If we kept a BootCodeReplacement FileSpecField--the first;               FileSpecField in the SuperScript--and are deleting a second;               occurrence, we need to continue the InnerLoop as if the;               pointer had just been updated, by checking for a;               FieldSeparator character -- so branch.	LongA On	rep #$0020	jsr ResolveOptions	bcs Check4Separator1;       After deleting the first occurrence of a FileSpec field, <ZPTemp will;       already be pointing at the next field, so we don't need to update the;       pointer, but we do need to set <ZPtemp1 = <ZPTemp and see if we're at;       the end of the script.	lda <ZPTemp	sta <ZPTemp1	lda <ZPTemp+2	sta <ZPTemp1+2	bra Check4Separator;       Strings don't match.NoMatch	LongA On	rep #$0020	bra InnerLoop	; No match; Before exiting, "blindly" resize the SuperScript's handle for the final; size in case we shrank it a bit.Exit	sec	; We're pointing at the 2nd	lda <ZPTemp	;   FieldSeparator...	sbc <ScriptPtr	tax	lda <ZPTemp+2	sbc <ScriptPtr+2	tay	inx	; ...so add one to the difference.	bne *+3	iny	jsr ResizeScriptMemory	rtsElimTemp	ds.b 1	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .ResolveOptions;; Description:	When two FileSpecFields are found that reference the;	same source and destination pathnames, control comes;	here to resolve conflicting options, if any, before;	one of them is deleted.;; Inputs:	none  (<ZPTemp points to the second FileSpecField);	      (<ZPTemp1 points to the first FileSpecField);; Outputs:	cFlag clear: First occurrence of a duplicate FileSpecField;	             was eliminated.;	cFlag set:   Second occurrance of a duplicate boot code;	             replacement FileSpecField was deleted.;; Side Effects:	A FileSpecField is deleted and the rest of the script;	is moved down.  Memory is NOT resized here!; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; If the FileSpec flags do not both contain a "B" flag, we must resolve the; differences.  (Ignore any other flags.)	lda [<ZPTemp1]	; Get 1st FileSpec flag	and #FlagB	;   and isolate "B" flag bit	sta Temp	lda [<ZPTemp]	; Get 2nd FileSpec flag	and #FlagB	;   and isolate "B" flag bit	cmp Temp	bne Resolve	; If they're different, gotta resolve em;       We have duplicate boot code replacement requests.  Delete the second;       FileSpecField and we're DONE!;       Need the pointer to the field to be deleted in <ZPTemp.	pei <ZPTemp+2	; Temporarily save on stack	pei <ZPTemp	lda <ZPTemp1	; Put the second FileSpecField	sta <ZPTemp	;   pointer into <ZPTemp	lda <ZPTemp1+2	sta <ZPTemp+2	jsr DeleteField1	; Delete the second FileSpecField	pla	; Restore original <ZPTemp	sta <ZPTemp	pla	sta <ZPTemp+2	sec	; Signify 2nd FileSpecField deleted	brl ResolveDone	Eject; Check to see if both flags are the same.  (We've pre-checked to catch them; if they were both a "B".)Resolve	lda [<ZPTemp1]	cmp [<ZPTemp]	beq DeleteFirst; The flags are not the same, we've got to resolve the differences!  Begin; with the optional flags.; If first FileSpec flag contains "D" flag, we can blindly delete it.	lda [<ZPTemp1]	; Get 1st FileSpec flag	and #FlagD	;   and isolate "D" flag bit	bne DeleteFirst	; If 1st DOES contain a "D"...; If second FileSpec flag contains "D" flag, we'll move the first 14 bytes of; data from the first FileSpecField to the second before deleteing the first,; thus using the flags and options in the first.	lda [<ZPTemp]	; Get 2nd FileSpec flag	and #FlagD	;   and isolate "D" flag bit	beq CheckFlagU	; If 2nd does NOT contain a "D"...	ldy #0012MoveLoop	lda [<ZPTemp1],y	; Move data from 1st FileSpecField	sta [<ZPTemp],y	;   to 2nd FileSpecField	dey	dey	bpl MoveLoopDeleteFirst1	bra DeleteFirst; If second FileSpec flag contains "U" flag and first does NOT, remove it; from the second flag word.CheckFlagU	lda [<ZPTemp]	; Get 2nd FileSpec flags	and #FlagU	;   and isolate "U" flag bit	beq RequiredFlags	; If 2nd does NOT contain a "U"...;       Second FileSpec flag DOES contain a "U".  Check the first.	lda [<ZPTemp1]	; Get 1st FileSpec flags	and #FlagU	;   and isolate "U" flag bit	bne RequiredFlags	; If 1st DOES contaIn a "U"...;       First FileSpec flag does NOT contain a "U".  Therefore, we must;       remove it from the second FileSpec flag.	lda [<ZPTemp]	and #$FFFF-FlagU	sta [<ZPTemp]	Eject; Isolate the required flags so we can resolve conflicts in them.RequiredFlags	lda [<ZPTemp]	; Get 2nd FileSpec flag	and #%1100000000000000 ; Isolate required flags	sta SecondFlag	lda [<ZPTemp1]	; Get 1st FileSpec flag	and #%1100000000000000 ; Isolate required flags	sta FirstFlag;       "2" flag takes precedence over "1", "3", or "4".	cmp #Flag2	; If 1st FileSpec flag is a "2",	beq Update2ndFlag	;   write it to the 1st FileSpec flag	lda SecondFlag	; If 2nd FileSpec flag is a "2",	cmp #Flag2	;   delete the 1st FileSpecField	beq DeleteFirst;       "1" flag takes precedence over "3" or "4".	lda FirstFlag	cmp #Flag1	; If 1st FileSpec flag is a "1",	beq Update2ndFlag	;   write it to the 1st FileSpec flag	lda SecondFlag	; If 2nd FileSpec flag is a "1",	cmp #Flag1	;   delete the 1st FileSpecField	beq DeleteFirst;       "4" flag takes precedence over "4".	lda FirstFlag	cmp #Flag4	; If 1st FileSpec flag is a "4",	beq Update2ndFlag	;   write it to the 1st FileSpec flag	lda SecondFlag	; If 2nd FileSpec flag is a "4",	cmp #Flag4	;   delete the 1st FileSpecField	beq DeleteFirst;       If first FileSpec required flag takes precedence over the second;       FileSpec required flag, store the first FileSpec required flag in;       the second FileSpec flag.Update2ndFlag	lda [<ZPTemp]	; Get the 2nd FileSpec flag	and #%0011111111111111 ; Clear the required bits	ora FirstFlag	; Store 1st FileSpec's required flag	sta [<ZPTemp]	;   in 2nd FileSpec flag.; Delete the first FileSpecField and we're DONE!DeleteFirst	jsr DeleteField1	clc	; Signify 2nd FileSpecField deleted.ResolveDone	rtsFirstFlag	ds.w 1SecondFlagTemp	ds.w 1	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CalcAndCopy	ProcName** Description:	Performs space calculation and then copies and/or*	deletes files according to the script instructions.*	(This subroutine is common to both InstallRemoveSubs and*	StandardUpdateSub - both Customized Install and Easy Update.)** Inputs:	none** Outputs:	carry set indicates error.** External Refs:	Import CopyProc	Import CancelStr	Import ContinueStr	Import CurrentVol	Import NotProDOS	Import NotProDOSEnd	Import SpaceCalc	Import SimpleKeyFilter	Import File_Sys_ID	Import CalculateSpace	Import CheckForInterrupt	Import CopyAndDeleteFiles	Import ExecFlag	Import GetFreeSpaceOnDest	Import SortSource	Import UpdateMsgWindow	Import TotalBlocksForInstall** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * **** moved to here 24-Mar-93 SS	stz TotalBlocksForInstall	stz TotalBlocksForInstall+2*** end 24-Mar-93 SS; Can only do a space calculation on a ProDOS volume	lda >File_Sys_ID	; Get the file system ID	cmp #ProDOSFileSys	beq CalcSpace; The volume is NOT ProDOS.  We can't calculate the space requirements.	ldx #InitCursor	jsl ToolLocator; specify the non-ProDOS volume name as the ^1 substitution string for the Alert.	lda >CurrentVol	; get length of Current Volume name	xba	; swap length word to make it a length byte	sta >CurrentVol	pea CurrentVol>>16	; string ^0: the non-ProDOS volume name	lda #CurrentVol	; low word	inc a	; point to length byte, not length word	pha	pea #0000	; string ^1: no change	pea #0000	pea #0000	; string ^2: no change	pea #0000	pea #0000	; string ^3: no change	pea #0000	ldx #ParamText	jsl ToolLocator; Let the user decide whether to continue.	pha	    ; Space for result	pea AlertTemplate1>>16  ; alertTemplatePtr	pea |AlertTemplate1	pea SimpleKeyFilter>>16 ; filterProcPtr	pea |SimpleKeyFilter	ldx #Alert	jsl ToolLocator	    ; Leave result on stack	ldx #WaitCursor	jsl ToolLocator	lda >CurrentVol	; put back word length of Current Volume name	xba	; swap length byte to make it a length word	sta >CurrentVol	pla	; Now, retrieve the result	cmp #0001	; If user hit OK, go ahead	beq CopyAndDelete	lda #-1	sec	bra Exit	; If user hit Cancel, we're done; Get free space on destination volume.CalcSpace	jsr GetFreeSpaceOnDest	bcs Exit	sec	; (Don't display "Unknown Mix" dialog)	jsr CheckForInterrupt ; Did user press OpenApple-<period>?	bcs Exit; Calculate space requirements	lda #SpaceCalc	; More info for user.	jsr UpdateMsgWindow	jsr SortSource	; organize scattered source disk FileSpecs together	bcs Exit	; exit if error	jsr CalculateSpace	; (and delete unneeded Update fields (no target))	bcs Exit	; canÕt proceed if not enough space on dest disk	sec	; (Don't display "Unknown Mix" dialog)	jsr CheckForInterrupt ; Did user press OpenApple-<period>?	bcs Exit; Delete and/or copy filesCopyAndDelete	lda #CopyProc	; Continue to keep user up to date	jsr UpdateMsgWindow	jsr CopyAndDeleteFiles	bcs Exit	sec	; Indicate that one or more scripts	ror ExecFlag	;  were executed.Exit	rts	Eject; This is the AlertTemplate for the dialog notifying the user that their; destination volume is NOT a ProDOS volume and, therefore, we cannot; determine the space requirements of the update.AlertTemplate1@Width    equ 370		; Local equates for the alert template@Height   equ 78@BtnWidth equ 80@MarginWid equ 20@Top      equ (200/2)-(@Height/2)+12@Left     equ (640/2)-(@Width/2)@Bottom   equ @Top+@Height@Right    equ @Left+@Width	dc.w @Top,@Left,@Bottom,@Right	dc.w $6789	 ; AlertID	dc.b $80,$80,$80,$80 ; Stage1, Stage2, Stage3, Stage4	dc.l @FirstItem	 ; First item template	dc.l @SecondItem	 ; Second item template	dc.l @ThirdItem	 ; Third item template	dc.l 00000000@FirstItem	dc.w 0001		; ItemID	dc.w @Height-20		; ItemRect	dc.w @Width-@MarginWid-@BtnWidth-2	dc.w @Height-8	dc.w @Width-@MarginWid-2	dc.w ButtonItem		; ItemType	dc.l ContinueStr		; ItemDescr	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColor@SecondItem	dc.w 0002		; ItemID	dc.w @Height-20		; ItemRect	dc.w @Width-@MarginWid-@MarginWid-@BtnWidth-@BtnWidth-4	dc.w @Height-8	dc.w @Width-@MarginWid-@MarginWid-@BtnWidth-4	dc.w ButtonItem		; ItemType	dc.l CancelStr		; ItemDescr	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColor@ThirdItem	dc.w 0003		; ItemID	dc.w 5,@MarginWid,@Height-21,@Width-@MarginWid  ; ItemRect	dc.w LongStatText2+ItemDisable	; ItemType	dc.l NotProDOS		; ItemDescr	dc.w NotProDOSEnd-NotProDOS	; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColor	EndP ;{CalcAndCopy}	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *GetFreeSpaceOnDest	Proc** Description:	Determine amount of free space on destination volume** Inputs:	none** Outputs:	none* Export	GetTargetDInfo** Description:	get device info of the target by first getting *	device number of CurrentVol, then doing DInfo** Inputs:	none** Outputs:	carry set if error from either GetDevNum or DInfo call** External Refs:	Import CurrentVol	; From Data.asm*	Import Error	; From MainSub.asm*	Import FreeSpace	Import GetInfoParms** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Check if the destination is write-protected.@1	jsr GetTargetDInfo	bcs @Exit	jsl GSOS	dc.w D_Status	dc.l D_Status_Parms	bcs @2	lda StatusList	and #%0000000000000100 ; Check "write protected" bit	beq @01	lda #WriteProtected	sec	bra @2; We're not write protected.  Get free space.; The only way I can see to get freeBlocks on the volume, with class 1 calls,; is to:;;       GetDevNumber  (volName --> devNum)          <-- [ALREADY DONE, ABOVE];       D_Info        (devNum  --> devName);       Volume        (devName --> freeBlocks)@01	jsl GSOS	dc.w Volume	dc.l Volume_Parms	bcc @3@2	ldx #CurrentVol	; Oops!	ldy #^CurrentVol	jsl Error	bcc @1	rts@3	lda VolFreeBlocks	sta FreeSpace	lda VolFreeBlocks+2	sta FreeSpace+2	lda #0000	clc@exit	rts	Eject; ENTRY:; get device info of the target by first getting device number of CurrentVolGetTargetDInfo	lda #CurrentVol	; Set up pathname pointer	sta GetDevNumName	lda #^CurrentVol	sta GetDevNumName+2@1	jsl GSOS	dc.w Get_Dev_Num	dc.l GetDevNumParms	; Borrow this parameter table	bcs @2	lda GetDevNumNum	; Contains the device number	sta D_Status_DevNum	sta D_Info_devNum	jsl GSOS	dc.w D_Info	dc.l D_Info_Parms	bcc @done@2	ldx #CurrentVol	; Oops!	ldy #^CurrentVol	jsl Error	bcc @1@done	rts; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetDevNumParms	dc.w 0002	; pCountGetDevNumName	ds.l 1	; devName  (Volume name)GetDevNumNum	ds.w 1	; devNumD_Status_Parms	dc.w 0005	; pCountD_Status_DevNum	ds.w 1	; devNumberD_Status_StatCode	dc.w 0000	; codeD_Status_StatPtr	dc.l StatusList	; listD_Status_ReqCnt	dc.l 00000006	; requestCountD_Status_TranCnt	ds.l 1	; transferCount	Export D_TargetDevIDD_Info_Parms	dc.w 0008	; pCountD_Info_devNum	ds.w 1	; devNum  (Device name)D_Info_devName	dc.l devName	; devName	ds.w 1	; characteristics	ds.l 1	; totalBlocks	ds.w 1	; slotNum	ds.w 1	; unitNum	ds.w 1	; versionD_TargetDevID	ds.w 1	; deviceIDVolume_Parms	dc.w 0004	; pCountVolDevName	dc.l devName+2	; devNameVolVolName	dc.l volName	; volNameVolTotalBlocks	ds.l 1	; totalBlocksVolFreeBlocks	ds.l 1	; freeBlocksStatusList	ds.b 6devName	dc.w 35	ds.b 33volName	dc.w 35	ds.b 33	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CompactScript	Proc** Description:	The following code compacts the Script file by stripping*	off the header, discarding all comments, and pre-processing*	the File Specification Fields.** Inputs:	none** Outputs:	none** External Refs:	Import CurrentVolBuf   ; From Data.asm	Import MyID	   ; From Data.asm*	Import Dereference	   ; From MainSub.asm	Import Error	   ; From MainSub.asm	Import GetAppDirPtr	   ; From MainSub.asm	Import GetCurDirPtr	   ; From MainSub.asm	Import ResizeCurDirBuf ; From MainSub.asm*	Import C1InpToGStr	   ; From GString.lib	Import GStrDispose	   ; From GString.lib	Import GStrNew	   ; From GString.lib	Import GStrResize	   ; From GString.lib	Import GStrToC1INP	   ; From GString.lib	Import GStrToGStr	   ; From GString.lib*	Import ExpandPathParms	Import ExpandInputPath	Import ExpandOutputPath*	Import CurFileInfo	import DeleteField	Import InstallVol	Import OldMemSize	Import ResizeScriptMemory	Import ScriptFlag	Import ScriptSize*	Import CurFileInfo	Import EndOfThisData	Import NoMoreFileSpecs	Import NumberOfFileSpecs	Import ScriptParentLevel	Import ThisFlagWord	Import ThisFileType	Import ThisAuxFileType	Import ThisFileDate	Import ThisSrcSize** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	Eject	stz NoMoreFileSpecs	; Clear these flags first	stz NumberOfFileSpecs	lda #$FFFF	; default if no ScriptParentFlag	sta ScriptParentLevel	jsl GetAppDirPtr	jsl GetCurDirPtr; Check the ScriptFlag word to be sure it is valid.  (I know...we already; accepted it once when we built the list of scripts at Installer startup.; but we didn't check it very well then.); check the third flag, ScriptParentFlag, for validity:  digit, dash, or return; set ScriptParentLevel based on this	ldy #ScriptFlagField+2	lda [<ZPTemp],y	and #$FF	cmp #Return	beq @testFirst2Flags  ; no 3rd or subsequent flags	cmp #'-'	beq @testFlag4  ; no-action 3rd flag: leave $FFFF in ScriptParentLevel	cmp #'0'	bcc @setError	; lower than '0': error	cmp #'9'+1	bcs @setError	; higher than '9': error	and #$000F	; convert '0'-'9' to 0-9	sta ScriptParentLevel; check the fourth flag, PreventBootFlag, for validity:  ÔbÕ, ÔBÕ or return@testFlag4	iny	; ScriptFlagField+3	lda [<ZPTemp],y	and #$FF	cmp #Return	beq @testFirst2Flags  ; no 4th or subsequent flags	and #%1111111111011111 ; (Make 2nd char case insensitive)	cmp #'B'	bne @setError	; error if not ÔbÕ or ÔBÕ ; Check the first two flags for validity@testFirst2Flags	ldy #ScriptFlagField	lda [<ZPTemp],y	tax	lda ScriptFlag	and #$00DF	; Look at 2nd char (UPPER case): 'X' or 'R'	cmp #'R'	; Is directory selection required?	beq @DontSetX	; bra if already 'R': don't reset it to 'X'	stx ScriptFlag	; else store whatever we've got now@DontSetX	txa	; get ScriptFlagField back	xba	; 1st char was in lo byte; swap to hi byte for easy reading	and #%1111111111011111 ; Make 2nd char case insensitive	cmp #'RR'	; Check for all legal combinations	beq @0	cmp #'XR'	beq @1	cmp #'RN'	beq @0	cmp #'XN'	beq @1@setError	sec	lda #$008D	jsl Error	brl ErrorExit; The script header specifies that the installation must occur in the root; directory of the user's currently specified volume.  So, move contents of; CurrentVolBuf into location pointed to by CurDirPtr for processing.@0	pea CurrentVolBuf>>16	pea |CurrentVolBuf	pei <CurDirPtr+2	pei <CurDirPtr	jsl GStrToGStr	jsl ResizeCurDirBuf	bcs @0	bra @2; The script header specifies that the installation must occur in the; user's specified Application directory.  So, move contents referenced by; AppDirHdl into location pointed to by CurDirPtr for processing.@1	pei <AppDirPtr+2	pei <AppDirPtr	pei <CurDirPtr+2	pei <CurDirPtr	jsl GStrToGStr	jsl ResizeCurDirBuf	bcs @1; Remove the first part of the header field up to and including the ; return before the source prefix entry.@2	jsr RemoveHeader; Extract the src prefix and delete the remainder of the header by moving; everything down so we are positioned at the beginning of the first FileSpec field	jsr ExtractSrcPrefix; Process each of the file specs in the script.	bra Check4FileSpecLoop	jsr ProcessFileSpec	bcs ErrorExit	lda NoMoreFileSpecs	; if last flag word was zero then we are done.	bne FinishCompacting; Find next FileSpec.  If the current <ZPTemp is pointing at an asterisk, we're; looking at a comment field, so delete it and try again.Check4FileSpec	lda [<ZPTemp]	and #$00FF	cmp #CommentChar	bne Loop	ldy #0	; seek to next field separator and delete	jsr SeekPastSeparator ; this field	jsr DeleteField	bra Check4FileSpec; Find out if we actually processed any FileSpec fields.  If not, terminate; processing.FinishCompacting	lda NumberOfFileSpecs	bne @0	brl ErrorExit@0; We've now stripped the header and all comments from the script and compacted; it into a smaller	space.  No need to resize the memory, upon return, the; calling routine will eventually dispose of it.;;;	lda #FieldSeparator;;;	sta [<ZPTemp];;;;;;	inc <ZPTemp;;;	bne @1;;;	inc <ZPTemp+2;;;@1;;;	lda [<ScriptHandle]	; Dereference the handle to find the;;;	sta <ZPTemp1	;   start of the script again;;;	ldy #0002;;;	lda [<ScriptHandle];;;	sta <ZPTemp1+2;;;;;;	sec	; Calculate size of	compacted script;;;	lda <ZPTemp;;;	sbc <ZPTemp1;;;	sta ScriptSize;;;	lda <ZPTemp+2;;;	sbc <ZPTemp1+2;;;	sta ScriptSize+2;;;	rtsErrorExit	sec	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .RemoveHeader;; Description:	Deletes all the characters in the script file from the;	beginning up to and including the first RETURN past the;	end of the comment field.;;	<ZPTemp is unchanged, but points to different data in;	the script.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	ldy #0000	; Find the double back-slash thatBackSlashLoop	lda [<ZPTemp],y	;  terminates the ScriptHelp	cmp #'\\'	beq FoundBackSlash	iny	bne BackSlashLoopFoundBackSlash	iny	iny	jsr SeekPastReturn	; Now get past the return character	jsr DeleteField	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .ExtractSrcPrefix;; Description:	If ScriptParentLevel is 0-9, extracts script directory (0),;	its parent (1), its grandparent (2), ... (9).;;	Then extracts the text from the point pointed to by <ZPTemp;	until the first field separator is reached, and appends it.;;	If there is neither ScriptParentLevel nor source prefix ;	specified in the script, we copy the name of the volume;	the installer is running from into the SrcPrefix.;;	SourcePfx is a memory segment obtained from the memory;	manager and the prefix is stored as a GStr.;;	After extracting the prefix we delete the rest of the;	header field and move everything down so that the first;	FileSpec is now at the beginning of the;	buffer.;; Inputs:	none;; Outputs:	none;; Uses:	ScriptParentLevel	(set to 0-9 to append a parent pathname or $FFFF); . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Get some memory to hold the source prefix	pha	; Room for result	pha	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer	plx	stx <SourcePfxPtr	ply	sty <SourcePfxPtr+2	bcc ExtractPrefix	; bra based on GStrNew success/failureEPMemoryError	lda #$0081	; Out of memory	jsl Error	brl Done; Does ScriptParentLevel hold a parent level # of the current script to use as a prefix?ExtractPrefix	ldx #0000	; 0 length so far	lda ScriptParentLevel	cmp #HighestParent+1  ; valid values of ScriptParentLevel: 0-9	bcs NoParentPrefix	; bra if no parent directory requested; X has 0 len; Use a parent of the directory the script is in; ScriptFilename holds a pathname like xx:Volume:path:scriptname where xx is length	tax	; save parentlevel	lda [<ScriptFilename]  ; get length of script filename	tay; Y holds length of ScriptFilename; X holds ScriptParentLevelFindParentLoop	lda [<ScriptFilename],y  ; start at 2nd-to-last char (y-1th char)	and #$00FF	; char in lo byte only	dey	; yth character in string itself	cpy #1	; limit: weÕre at the leading colon	beq CopyParent	cmp #SeparatorChar	; is char in lo byte a colon?	bne FindParentLoop	; loop if not a separator char	dex	; found a colon	bpl FindParentLoop	; loop if still looking for more parents; Parent prefix is the first Y chars of ScriptFilename; copy to SourcePfxPtr (GS/OS output string: xx:xx:Volume:path)CopyParent	dey	; donÕt include trailing colon	tyx	; save length in XCopyParentLoop	lda [<ScriptFilename],y  ; get word starting 2 bytes before trailing colon	iny	; past output string overhead (bufferlen)	iny	sta [<SourcePfxPtr],y	dey	; unto output string overhead	dey	dey	; go to previous word	dey	bpl CopyParentLoop; Now append the source prefix in the script to the scriptParentPrefix already in SourcePfxPtr; X reg holds current length of SourcePfxPtr string	sep #$20	LongA Off	lda [<ZPTemp]	; get the first char	cmp #FieldSeparator	beq EndOfPrefix	; bra if no prefix in script header (done); check for initial separator on scriptPrefix	cmp #'/'	; compare 1st char	beq ExtractLoopInit	; if initial separator, can append to scriptParent ok	cmp #SeparatorChar	beq ExtractLoopInit; no initial separator: add a trailing separator to scriptParent before appending scriptPrefix	inx	; increment length for separator	txy	iny	; increment past output string overhead	iny	iny	lda #SeparatorChar		sta [<SourcePfxPtr],y; now move scriptPrefix from ZPTemp; X reg holds current length of SourcePfxPtr stringNoParentPrefix	sep #$20	LongA OffExtractLoopInit	ldy #0000	; init ZPTemp index & lengthExtractLoop	lda [<ZPTemp],y	cmp #FieldSeparator	beq EndOfPrefix	cmp #'/'	; Gotta change '/' to SeparatorChar	bne @1	lda #SeparatorChar@1	phy	; save ZPTemp index	inx	; increment length	txy	iny	; increment past output string overhead	iny	iny	sta [<SourcePfxPtr],y	ply	; restore ZPTemp index	iny	bra ExtractLoop; X reg holds length of SourcePfxPtr stringEndOfPrefix	rep #$20	LongA ON	txa	; Put length into A so can store; If source prefix is of len zero, there was no source prefix specified in the script.; (or a scriptParent flag drove the parent level higher than the volume name!)	bne GotPrefix	ldx ScriptParentLevel	cpx #HighestParent+1  ; valid values of ScriptParentLevel: 0-9	bcs UseVolumeName	; bra if no parent directory requestedGotPrefix	ldy #0002	;   length word	sta [<SourcePfxPtr],y	pha	; If it didn't fit the first time,	pha	;   try again.	pei <SourcePfxPtr+2	pei <SourcePfxPtr	jsl GStrResize	pla	sta <SourcePfxPtr	pla	sta <SourcePfxPtr+2	bcc PrefixOK	cmp #0004	; GStrBufferError ?	bne EPMemoryErrorJ	brl ExtractPrefix; If the source prefix is of length zero, there was no source prefix; specified in the script, so use the Installer program's volume nameUseVolumeName	lda <SourcePfxPtr	; Get prefix #9 (the directory from	sta GetPfxPath	;   which the Installer was launched).	lda <SourcePfxPtr+2	sta GetPfxPath+2@0	jsl GSOS	dc.w Get_Prefix	dc.l GetPfxParms	pha	; If it didn't fit the first time,	pha	;   try again.	pei <SourcePfxPtr+2	pei <SourcePfxPtr	jsl GStrResize	pla	sta <SourcePfxPtr	pla	sta <SourcePfxPtr+2	bcc BeginSearch	cmp #0004	; GStrBufferError ?	beq @0EPMemoryErrorJ	brl EPMemoryErrorBeginSearch; Change the length word to truncate the prefix to just a volume name (strip path).	ldy #0004	; Skip leading separator character (iny yields 5)@Search	iny	lda [<SourcePfxPtr],y	and #$00FF	; just char in low byte	cmp #SeparatorChar	bne @Search; found the volumeÕs trailing separator char	tya	; Convert index into length word	sec	sbc #0004	; subtract 4th to not include trailing colon	ldy #0002	;   and store back into the GStr	sta [<SourcePfxPtr],y	pha	; Resize the memory for perfect fit.	pha	pei <SourcePfxPtr+2	pei <SourcePfxPtr	jsl GStrResize	pla	sta <SourcePfxPtr	pla	sta <SourcePfxPtr+2; Moving right along...  Delete the remainder of the header.PrefixOK	jsr SeekPastSeparator ; (No comments permitted.)	jsr DeleteFieldDone	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .SeekPastReturn;; Description:	Starting at current y-reg, look at the characters in the;	buffer and find the next return (0D).  Return with the;	y-reg set to one past the first return.;;	If seeking past the next return should for some reason;	get us past the end of the script, an error is displayed;	and this routine exits through an escape hatch in the;	main InstallSub that cleans up the stack.;; Inputs:	none;; Outputs:	cFlag clear: no error;	cFlag set: no return found before reaching end of script.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	sep #$20	LongA Off@Loop	lda [<ZPTemp],y	cmp #Return	beq @GotIt	iny	cpy ScriptSize	bne @Loop; If we get to this point, we went to far in the script.	rep #$20	LongA On	lda #$0085	; Display the error	sec	jsl Error	rts@GotIt	iny	rep #$20	LongA On	clc	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .SeekPastSeparator;; Description:	Starting at current y-reg, look at the characters in;	the buffer and find the next separator character (~).;	Return with the y-reg set to one past the first separator.;;	If seeking past the next separator should for some reason;	get us past the end of the script, an error is displayed;	and this routine exits through an escape hatch in the;	main InstallSub that cleans up the stack.;; Inputs:	Y is index into ZPTemp.;; Outputs:	cFlag clear: no error;	    Y is index into ZPTemp, set to one past the separator char.;	cFlag set: no separator found before reaching end of script.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	sep #$20	LongA Off@Loop	lda [<ZPTemp],y	cmp #FieldSeparator	beq @GotIt	iny	cpy ScriptSize	bne @Loop; If we get to this point, we went too far in the script.	rep #$20	LongA On	lda #$0085	; Display the error	sec	jsl Error	rts@GotIt	iny	rep #$20	LongA On	clc	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .ProcessFileSpec	Name;; Description:	<ZPTemp Points to the first byte of a file spec (after;	the separator).;;	This routine processes the file spec by putting all the;	information  into the temporary fields at the top of;	this file.;;	Slashes in filenames are translated to colons.;;	After the information is extracted, it's copied back;	into the script in this compacted form.;; Inputs:	none;; Outputs:	cFlag Clear: no errors;	cFlag Set: error occurred; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Start by zeroing out all the current variables	ldx #EndOfThisData-CurFileInfo-2@1	stz CurFileInfo,x	dex	dex	bpl @1	stz CurFileInfo	; (Just in case the data was not		;   an even number of bytes...)	stz ReqFlag	; Zero the Required Flag too; Get the first character of the field.  If it's not a FieldSeparator, there; is more script to process.	lda [<ZPTemp]	and #$00FF	cmp #FieldSeparator	bne MoreScriptToGo; There's no more script to process.	lda #True	sta NoMoreFileSpecs	clc	rts; There is more script to process!MoreScriptToGo	inc NumberOfFileSpecs	ldy #FlagsWord+$10	; Initial Y-reg to process the flagsFlagLoop	lda [<ZPTemp],y	; Last flag is followed by a <return>	and #$00FF	cmp #Return	beq DoneWithFlags	phy	jsr UpdateFlagWord	ply	bcc @1	brl Exit@1	jsr SeekPastReturn	; Must return y	bra FlagLoop; We've handled all the flags.  Now check that the rules were followed...;      1.)  There is a required flag;      2.)  "U" flag requires a "1" or "2" flag.;      3.)  "B" flag requires a "2" flag.;      4.)  "D" flag requires a "4" flag.DoneWithFlags	bit ReqFlag	bmi BadFormat	lda ThisFlagWord	; Get the flag word	bit #FlagU	; Check for "U" flag	beq @1	; If "U" flag not set, go on	bit #%1011111111111111 ; Check for other than "1" or "2" flag	beq BadFormat	; If other than "1" or "2" set, bad format@1	bit #FlagD	; Check for "D" flag	beq @2	; If "D" flag not set, go on	bit #Flag4	; Check for "4" flag	beq BadFormat	; If "4" not set, bad format@2	bit #FlagB	; Check for "B" flag	beq FlagsOK	; If "B" flag not set, go on	bit #Flag2	; Check for "2" flag	bne FlagsOK	; If "2" is set, we're OKBadFormat	lda #$0086	; Oops...bad script	format	sec	jsl Error	brl ExitFlagsOK	iny	; Bump y past last return; Process the type information (if any)	phy	jsr ProcessTypeInfo	ply	jsr SeekPastReturn; Process the date	phy	jsr ProcessDateInfo	ply	jsr SeekPastReturn	sty Index; Extract the pathnames;       Get some memory to save the prefix	pha	; Room for result	pha	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer	plx	stx SavePfxPath	ply	sty SavePfxPath+2	bcs PFSMemoryError;       Save the current system prefixSavePrefix	jsl GSOS	dc.w Get_Prefix	dc.l SavePfxParms;       If it didn't fit, resize the buffer and try again.	pha	; If it didn't fit, resize the buffer	pha	;   and try again.	lda SavePfxPath+2	pha	lda SavePfxPath	pha	jsl GStrResize	pla	sta SavePfxPath	pla	sta SavePfxPath+2	bcc @NoError	cmp #0004	; GStrBufferError ?	beq SavePrefix	bra PFSMemoryError;       Get some memory for the source pathname@NoError	pha	; Room for result	pha	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer	plx	stx <SourcePtr	ply	sty <SourcePtr+2	bcc PFSNoMemoryErrorPFSMemoryError	lda #$0081	; Out of memory	jsl Error	brl ExitPFSNoMemoryError;       Build us a full pathname in SourcePtr.; First move SourcePfxPtr (the prefix) into SourcePtrExpandSourceName	pei <SourcePfxPtr+2	pei <SourcePfxPtr	pei <SourcePtr+2	pei <SourcePtr	jsl GStrToGStr;       The source pathname in the script is a <return> terminated string.;       Make it a GS/OS Class 1 input string.  (We can overwrite;       stuff ahead of it--we're through with that info.);       Also count chars, and convert '/'s to ':'s.	clc	; Point to the input pathname	lda <ZPTemp	adc Index	tax	lda <ZPTemp+2	adc #0000	pha	phx	jsr FixPathname	; convert to C1, count chars, substitute colons	pha	; push the length (pointer to C1 string already on stack); Is the script pathname a full pathname or a partial pathname?	ldy Index	; Point to the input pathname	lda [<ZPTemp],y	; get first char	and #$00FF	; lo byte only	cmp #SeparatorChar	beq GotFullPath; No separator at start of scriptPath;; so add separator to end of prefix, then append scriptPath.		ldy #0002	lda [SourcePtr],y	; get prefix length	tax	; save previous (prefix) length in X	pla	; length of scriptPath	inc a	; add 1 to count separator char we'll add	clc	adc [SourcePtr],y	; add prefix length	sta [SourcePtr],y	; new combined length	ply	; (discard pointer to C1 string)	ply	; (hi)	dec a	; (equal becomes less, for branch)	cmp [SourcePtr]	; check combined length-1 against size of buffer	bcs ResizeBuff	; if new leng is bigger (len-1 is >=), resize buffer		sep #$20	longa off	inx	; X has length of previous (prefix) in SourcePtr	inx	; increment to point to next available buffer position	inx	; (make it an index)	lda #SeparatorChar	; store a colon before appending scriptPath	ldy Index	; offset in ZPTemp to scriptPathCopyScriptPathLoop	phy	; save ZPTemp index	inx	; point result index to next free byte	txy	sta [SourcePtr],y	; store the char	ply	lda [<ZPTemp],y	; get scriptPath char	iny	; point source index to next char	cmp #Return	; ReturnChar doesnÕt get moved	bne CopyScriptPathLoop	rep #$20	longa on	bra ResizeBuff	; Separator at start of script; this is a full pathname.; Copy it whole (no prefix) to SourcePtr.; Length of scriptPath & Pointer to C1 version of scriptPath are still on the stack.GotFullPath	pla	; pull scriptPath len off stack (discard)	pei <SourcePtr+2	; (pointer to scriptPath is already on stack)	pei <SourcePtr	jsl C1InpToGStrResizeBuff	pha	; If it didn't fit, resize the buffer	pha	;   and try again.	pei <SourcePtr+2	pei <SourcePtr	jsl GStrResize	pla	sta <SourcePtr	pla	sta <SourcePtr+2	bcc GetDestName	cmp #0004	; GStrBufferError ?	beq ExpandSourceNamePFSMemoryError1	brl PFSMemoryError;       Get some memory for the destination pathname.GetDestName	pha	; Room for result	pha	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer	plx	stx <DestPtr	ply	sty <DestPtr+2	bcs PFSMemoryError1;       Let GS/OS build us a full pathname.	clc	; Point to the strings lengthWord	lda <CurDirPtr	adc #0002	sta SetPrefixPath	lda <CurDirPtr+2	adc #0000	sta SetPrefixPath+2	jsl GSOS	; Set the system prefix	dc.w Set_Prefix	dc.l SetPrefixParms	ldy Index	jsr SeekPastReturn	sty Index	clc	; Point to the input pathname	lda <ZPTemp	adc Index	tax	lda <ZPTemp+2	adc #0000	pha	phx	jsr FixPathname	; convert to C1, count chars, substitute colons	pla	sta ExpandInputPath	pla	sta ExpandInputPath+2ExpandDestName	lda <DestPtr	; Point to the output pathname buffer	sta ExpandOutputPath	lda <DestPtr+2	sta ExpandOutputPath+2	jsl GSOS	; Build a full pathname in the memory	dc.w Expand_Path	dc.l ExpandPathParms	pha	; If it didn't fit, resize the buffer	pha	;   and try again.	pei <DestPtr+2	pei <DestPtr	jsl GStrResize	pla	sta <DestPtr	pla	sta <DestPtr+2	bcc StoreData	cmp #0004	; GStrBufferError ?	beq ExpandDestNamePFSMemoryError3	brl PFSMemoryError; Resize the SuperScript's memory to hold the acquired information:; 16 bytes (data) + 4 bytes (2 lengthWords) + source pathname + destination name.StoreData	ldy #4	; Unlock the handle	lda [<ScriptHdl],y	and #$FFFF-attrLocked	sta [<ScriptHdl],y; Save the old memory size in "Temp" and calculate the new memory size needed.; Then resize the memory and get the pointer,	pha	; Get current SuperScript memory size	pha	pei <ScriptHdl+2	pei <ScriptHdl	ldx #GetHandleSize	jsl ToolLocator	clc	; Calculate new memory size	pla	sta Temp	adc #0021	; Data size + 2 lengthWords + tilde	ldy #0002	adc [<SourcePtr],y	; Source pathname size	adc [<DestPtr],y	tax	pla	sta Temp+2	adc #0000	tay	jsr ResizeScriptMemory	bcc @GoAhead	brl Exit@GoAhead	lda <ScriptPtr	sta <ZPTemp	lda <ScriptPtr+2	sta <ZPTemp+2; Set up <ZPTemp2 as the pointer to the beginning of the new FileSpec in the; SuperScript.	