y	; 2nd two characters didn't match,	dey	;  restore 1st two characters & continue	lda [<ZPTemp],y	and #%0101111101011111 ; Make both char	case insensitive	bra MonthLoop1FoundMonth	dex	; Found a match	dex	;  so back up	txa	asl a	; Already shifted 2	places,	asl a	;  so shift 3 more	asl a	ora ThisFileDate	sta ThisFileDate	ldy Temp	; Restore search index,	iny	;  and update to next	iny	iny	iny	sty Temp;       Finally, the year--move it left 9 bits before combining with day/month	pha	; Space for result	clc	; Calculate location of year string	tya	adc <ZPTemp	tax	lda #0000	adc <ZPTemp+2	pha	; Pointer to string	phx	pea 0002	; String length	pea 0000	; not signed	ldx #Dec2Int	jsl ToolLocator	pla	; Get result	bcc YearOKBadFormat1	lda #$0086	; Oops...bad script	format	sec	jsl Error	rtsYearOK	xba	; Move result up 9 bits	asl a	ora ThisFileDate	sta ThisFileDate; So we have the day, lets get the time.; First, the hours in the high order byte of CreationTime	ldy Temp	; Get the search index	iny	;  and update it	iny	iny	sty Temp	pha	; Space for result	clc	; Calculate location of hours string	tya	adc <ZPTemp	tax	lda #0000	adc <ZPTemp+2	pha	; Pointer to string	phx	pea 0002	; String length	pea 0000	; Un-signed	ldx #Dec2Int	jsl ToolLocator	pla	; Get result	bcs BadFormat1	xba	; Move to high byte	sta ThisFileDate+2; Finally, the hours in the high order byte of CreationTime	ldy Temp	; Get search index	iny	;  and update it	iny	iny	sty Temp	pha	; Space for result	clc	; Calculate location of minute string	tya	adc <ZPTemp	tax	lda #0000	adc <ZPTemp+2	pha	; Pointer to string	phx	pea 0002	; String length	pea 0000	; Un-signed string	ldx #Dec2Int	jsl ToolLocator	pla	; Get result	bcs BadFormat1	ora ThisFileDate+2	sta ThisFileDate+2	clc	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .FixPathname;; Description:	Creates a GS/OS Class 1 input string from a <return>;	terminated string, pointed to by parameter on stack, by;	adding a lengthWord ahead of the string then replacing;	the parameter on the stack with a new pointer that points;	to the lengthWord.  Also translates '/' to ':'.;; Inputs:	Pointer to the <return> terminated string.;; Outputs:	Pointer to the GS/OS Class 1 input string.;	Accum still holds length word.;; NOTE:	This routine assumes that the two bytes ahead of the;	<return> terminated string can safely be overwritten!; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	phd	tsc	tcd	sep #$20	Longa Off	ldy #$0000@Loop	lda [$05],y	; Search for the <return>	cmp #'/'	bne @notSep	lda #SeparatorChar	; if '/', replace with ':'	sta [$05],y@notSep	cmp #Return	beq @FoundReturn	iny	bne @Loop@FoundReturn	LongA On	rep #$20	phy	; Save the lengthWord	lda $05	; Back the pointer up to point	bne *+4	;   to the lengthWord we're going	dec $07	;   to create	dec $05	bne *+4	dec $07	dec $05	pla	sta [$05]	pld	rts; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Local data for CompactScript; These are the legal flags that may be	found in a script.FlagList	dc.b '1234'	; All the legal FlagSpec flagsRequiredFlag	equ *-FlagList	dc.b 'BCFUD'FlagListSize	equ *-FlagList; These are the bit	patterns associated	with the above flags.	Entry FlagBitsFlagBits	dc.w Flag1	; '1' flag	dc.w Flag2	; '2' flag	dc.w Flag3	; '3' flag	dc.w Flag4	; '4' flag	dc.w FlagB	; 'B' flag	dc.w FlagC	; 'C' flag	dc.w FlagF	; 'F' flag	dc.w FlagU	; 'U' flag	dc.w FlagD	; 'D' flag; These are the months of the yearMonths	dc.b 'JAN '	dc.b 'FEB '	dc.b 'MAR '	dc.b 'APR '	dc.b 'MAY '	dc.b 'JUN '	dc.b 'JUL '	dc.b 'AUG '	dc.b 'SEP '	dc.b 'OCT '	dc.b 'NOV '	dc.b 'DEC 'ReqFlag	ds.w 1	; Hi-bit set = A required flag was foundTemp	ds.w 1Index	ds.w 1GetPfxParms	dc.w 0002	; pCount	dc.w 0009	; prefixNumGetPfxPath	ds.l 1	; pathnameSavePfxParms	dc.w 0002	; pCount	dc.w 0008	; prefixNumSavePfxPath	ds.l 1SetPrefixParms	dc.w 0002	; pCount	dc.w 0008	; prefixNumSetPrefixPath	ds.l 1	; pathname	EndP ;{CompactScript}	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CalculateSpace	ProcName** Description:	A compacted script is now in memory.  We must now*	determine the space required to be sure the destination*	volume has enough space.**	First, we'll make a pass through the source disk getting*	the number of blocks for every source file.  Then, we'll*	make a pass through the destination volume while keeping*	a running talley of blocks to be freed up and additional*	blocks needed.  If we can't make it, we'll notify the*	user.** Inputs:	none** Outputs:	carry clear unless thereÕs a space problem.** External Refs:	Import Err88Blocks	; From Data.asm	Import MyID	Import UpdateFlag*	Import Dereference	; From MainSub.asm	Import Error*	Import C1InpToC1Inp	; From GString.lib*	Import CloseParms	Import CloseRefNum	Import ConvertDateTime	Import CurDirectory	Import DeleteField1	Import FreeSpace	Import GetInfoParms	Import GetInfoDate1	Import GetInfoTime1	Import NextFileSpec	Import OpenRefNum	Import OpenParms	Import OpenPath	Import RemoveFlag	Import TotalBlocksForInstall** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	Eject; If we're REMOVEing, there is nothing to do.	bit RemoveFlag	bpl @1	brl SpaceEnd; Initialize everything@1;	stz TotalBlocksForInstall  ;*** moved earlier in time 24-Mar-93 SS;	stz TotalBlocksForInstall+2	stz DataHandle	; Clear the handle to the 1st data	stz DataHandle+2	;  structure	stz LargestSize	; Zero-out size	stz LargestSize+2;	lda <ScriptPtr	; Put the script pointer in	sta <ZPTemp	;  ZPTemp	lda <ScriptPtr+2	sta <ZPTemp+2; This is the main loop for checking size of source files.SourceSpaceLoop; If the FlagWord has Flag3 set, we're just going to delete the destination; file, if it exists, and there is no source pathname.	lda [<ZPTemp]	; Get the FlagsWord	and #Flag3	beq @00	; If hi-bit clear, go on; It is a deletion request.  The source file doesn't exist (size = zero)	stz GetInfoUsed	; Source file is size = zero	stz GetInfoUsed+2	stz GetInfoResUsed	stz GetInfoResUsed+2	brl StoreBlocks; Find out about the file.@00	clc	; Calculate the address of the source	lda <ZPtemp	;   pathname	adc #Pathnames	sta GetInfoPath	lda <ZPTemp+2	adc #0000	sta GetInfoPath+2@0	jsl GSOS	dc.w Get_File_Info	dc.l GetInfoParms	bcc @1	ldx GetInfoPath	ldy GetInfoPath+2	jsl Error	bcc @0	brl ErrorExit; Check to see if this file is bigger than the largest size we have; stored so far.@1	clc	; Add data and resource sizes together	lda GetInfoEOF	; (data fork EOF)	adc GetInfoResEOF	sta TotalFileSize	lda GetInfoEOF+2	adc GetInfoResEOF+2	sta TotalFileSize+2		lda TotalFileSize	cmp LargestSize	lda TotalFileSize+2	sbc LargestSize+2	bcc CheckFlagWord	lda TotalFileSize	sta LargestSize	lda TotalFileSize+2	sta LargestSize+2; Check the FlagsWord and see if Creation Date/Time must match.CheckFlagWord	lda [<ZPTemp]	; Get FlagsWord	and #FlagC	; Must the creation	match?	beq NextFlag;       The Creation Date/Time must match (First convert to ProDOS format)	jsr ConvertDateTime	ldy #CreationDate	; Check CreationDate	lda [<ZPTemp],y	cmp GetInfoDate1	bne Oops	ldy #CreationTime	; Check CreationTime	lda [<ZPTemp],y	cmp GetInfoTime1	beq NextFlagOops	sec	; If any required match fails, notify user	lda #$0087	jsl Error	brl ErrorExit; Check the FlagsWord and see if File/Aux Type must match.NextFlag	lda [<ZPTemp]	; Get FlagsWord	and #FlagF	; Must the file/aux	type match?	beq StoreBlocks;       The File/Aux types must match	ldy #FileTypeWord	; Check FileType	lda [<ZPTemp],y	cmp GetInfoFileType	bne Oops	ldy #AuxTypeLWord	; Check AuxType	lda [<ZPTemp],y	cmp GetInfoAuxType	bne Oops	iny	iny	lda [<ZPTemp],y	cmp GetInfoAuxType+2	bne Oops; Get the number of	blocks and store itStoreBlocks	clc	ldy #SourceSize	lda GetInfoUsed	adc GetInfoResUsed	sta [<ZPTemp],y	iny	iny	lda GetInfoUsed+2	adc GetInfoResUsed+2	sta [<ZPTemp],y; Update Total blocks for install	clc	lda GetInfoUsed	adc GetInfoResUsed	adc TotalBlocksForInstall	sta TotalBlocksForInstall	lda GetInfoUsed+2	adc GetInfoResUsed+2	adc TotalBlocksForInstall+2	sta TotalBlocksForInstall+2; Update zero page pointer to point to next FileSpec field and loop until all; FileSpec fields have been checked	jsr NextFileSpec	bcs @1	brl SourceSpaceLoop@1	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .;; We now have verified that source files meet matching criteria; and have stored the size of each file	in our compacted script.; The next major step is to go through the destination names and; determine space to be freed through deletions and space needed; through copies.  Don't forget to figure in additional directories; that must be created.;................................................................; Initialize enerything	stz NegativeFlag	; Clear variables and flags	stz NegSpace	stz NegSpace+2	lda <ScriptPtr	; Put pointer to beginning of the	sta <ZPTemp	;  SuperScript into <ZPTemp	lda <ScriptPtr+2	sta <ZPTemp+2; First, get the index to the destination pathnameSpaceLoop	ldy #Pathnames	lda [<ZPTemp],y	; Get length word of source name...	inc a	inc a	sta Temp	clc	; Calculate offset to destination name	tya	adc Temp	pha	; Save on stack; Calculate offset to destination name for NewFile subroutine	clc	tya	adc Temp	adc <ZPTemp	sta <ZPTemp1	lda #$0000	adc <ZPTemp+2	sta <ZPTemp1+2; Put the destination pathname pointer the Get_File_Info parameter table and; make the call	clc	pla	; Get index from stack (see above)	adc <ZPTemp	sta GetInfoPath	lda #0000	adc <ZPTemp+2	sta GetInfoPath+2	stz CallFailedFlag@0	jsl GSOS	dc.w Get_File_Info	dc.l GetInfoParms	bcc @3	cmp #VolumeNotFound	bne @2	ldx GetInfoPath	ldy GetInfoPath+2	jsl Error	bcc @0	brl ErrorExit; The call failed.  If the flag was a "3" or "4", we're simply removing and; we can ignore the error.  Likewise, if the flag was a "B", it's boot code; replacement, and, again, we can just ignore the error@2	sec	; Set the CallFailed flag	ror CallFailedFlag	tax	; Save the error code	lda [<ZPTemp]	; Get the FlagsWord	and #%1000000000000000 ; Was flag a "3" or "4"?	bne @3	lda [<ZPTemp]	; Get the FlagsWord	and #FlagB	; Was flag a "B"?	bne @3	txa	; Restore the error code	brl CallFailed@3; The call was successful.  SourceSize longword of the current FileSpec field in; memory has the size of the source file, GetInfoUsed has the size of the; destination file,	and FreeSpace contains the free space on the volume.;       Check REMOVE flag to see if we're REMOVEing or INSTALLing.	bit RemoveFlag	bpl CheckForDFlag	; We're INSTALLing--always delete destination;       We're REMOVEing, so check the FlagWords to see if the file;       should be deleted	lda [<ZPTemp]	; Get FlagsWord	and #%0100000000000000 ; Check bit 14	bne DontDelete;       Check for the "D" flag, a conditional deletion, and determine if;       file is really to be deleted or not.CheckForDFlag	lda [<ZPTemp]	bit #FlagD	; Check for "D" flag	beq DeleteIt; If "D" flag is set, we have to compare dates and times and only delete; the file if it is older than the FileSpec's creation date/time;       First convert to ProDOS format	lda GetInfoCreation+4 ; Get Month/Day	and #$00FF	; Mask off month	inc a	; (Day returned as 0-30 not 1-31!)	sta GetInfoDate1	; Save the day in prodos format	lda GetInfoCreation+5 ; Get Null/Month	and #$00FF	; Mask off null	inc a	; (Month returned as 0-11 not 1-12!)	asl a	asl a	asl a	asl a	asl a	; Shift to correct position	ora GetInfoDate1	; Month is now happy	sta GetInfoDate1	lda GetInfoCreation+3 ; Get Day/Year	and #$00FF	; Mask off day	xba	asl a	; Shift year to upper 7 bits	ora GetInfoDate1	sta GetInfoDate1	lda GetInfoCreation+1 ; Get Hour/Minutes	and #$00FF	; Mask off hour	sta GetInfoTime1	lda GetInfoCreation+2 ; Get Year/Hour	and #$00FF	; Mask off year	xba	ora GetInfoTime1	sta GetInfoTime1;       Now, do the comparison.	bit RemoveFlag	bmi DontDelete	; Ignore "D" on REMOVE	ldy #CreationTime	lda GetInfoTime1	cmp [<ZPTemp],y	dey	dey	lda GetInfoDate1	sbc [<ZPTemp],y	bcs DontDelete;       The destination file is to be removed.  Add its size to FreeSpace;       unless call failed is set.DeleteIt	bit CallFailedFlag	bmi DontDelete	clc	lda FreeSpace	adc GetInfoUsed	adc GetInfoResUsed	sta FreeSpace	lda FreeSpace+2	adc GetInfoUsed+2	adc GetInfoResUsed+2	sta FreeSpace+2DontDelete;       Re-check the REMOVE flag to see if we're REMOVEing or INSTALLing.	bit RemoveFlag	bmi GetNextFileSpec	; If REMOVEing, we're done;       We're INSTALLing so check the FlagsWord to see if we must copy;       the source file over.	lda [<ZPTemp]	; Get FlagsWord	and #%1000000000000000 ; Check bit 15	bne GetNextFileSpec	; If set, no file to copy.;       We're going to copy the source file so deduct its size from;       the FreeSpace value.CopySource	ldy #SourceSize	lda [<ZPTemp],y	; Get the source file size	sta Temp	iny	iny	lda [<ZPTemp],y	sta Temp+2	sec	; Keep a running talley of free space	lda FreeSpace	sbc Temp	sta FreeSpace	lda FreeSpace+2	sbc Temp+2	sta FreeSpace+2	bmi NoSpace	; If negative space, won't fit; Update <ZPTemp to point to the next FileSpec fieldGetNextFileSpec	jsr NextFileSpec	bcs SpaceExit1	; End-of-script	brl SpaceLoop	; Keep loopingSpaceExit1	brl SpaceExit;       Oops!  The FreeSpace value went negative!  We can't perform the;       desired operation on this disk.  Notify the user.NoSpace	sec	; Set NegativeFlag	ror NegativeFlag	lda NegSpace	; Is NegSpace still zero?	bne @1	lda NegSpace+2	beq @2@1	lda FreeSpace	; Are we more negative than the last?	cmp NegSpace	lda FreeSpace+2	sbc NegSpace+2	bcs GetNextFileSpec	; If not, continue@2	lda FreeSpace	; Maintain the MOST	negative value we	sta NegSpace	;  encounter so we can report how much	lda FreeSpace+2	;  more space is needed when we finish	sta NegSpace+2	bra GetNextFileSpec; Oops!  The call failed!CallFailed	cmp #PathNotFound	; Couldn't find the path?	beq NoFile	cmp #FileNotFound	; Couldn't find the file?	beq NoFile	sec	; Some other kind of error	jsl Error	brl ErrorExit; Couldn't find the file or the path, one or the other.  In either case, the; file doesn't exist.  There is no FreeSpace to be gained.  We don't have to; copy the source file if the 'update only' (U) flag has been set.NoFile	lda [<ZPTemp]	; Get the FlagsWord	and #FlagU	bne @1	; If FlagU set, the field is moot.;       The 'update only' flag is NOT set.  We're going to create a new;       file on the destination volume.  We must check to see if the;       directory is going to grow a block as a result.	jsr NewFile;       Now use existing routines to take care of updating the talley;       for the file's needs, and continue.	bra CopySource	; If FlagU clear, we must copy source file;       There is no destination file and the 'update only' flag is set.;       We must subtract this fileÕs size from the total size.;       Then we can delete this FileSpec field since there is absolutely;       nothing for us to do.@1	sec	ldy #SourceSize	lda TotalBlocksForInstall	sbc [<ZPTemp],y	; subtract # of blocks in this filespec	sta TotalBlocksForInstall	iny	iny	lda TotalBlocksForInstall+2	sbc [<ZPTemp],y	; subtract # of blocks in this filespec	sta TotalBlocksForInstall+2	jsr DeleteField1	bcs SpaceExit	; End-of-script	brl SpaceLoop	; Keep looping; We've finished checking the space requirements.  If our FreeSpace value went; negative at any time, notify the user	of the additional space needed and; do not continue with the requested operation.SpaceExit	bit NegativeFlag	bmi Error1	jsr DisposeMemorySpaceEnd	lda #0000	clc	rts;       Calculate the additional space required, plug the value in at;       Err88Blocks (four ASCII bytes), and display the message.Error1	sec	lda #0000	sbc NegSpace	; This value is in blocks.	lsr a	; Divide by 2 to get KiloBytes.	inc a	; Be sure value is NEVER zero		; Convert the value to ASCII	pha	; wordValue	pea Err88Blocks>>16	; strPtr	pea |Err88Blocks	pea 0005	; strLength	pea False	; signedFlag	ldx #Int2Dec	jsl ToolLocator	sep #$30	LongA Off	LongI Off	ldy #$FF	; Pad left end of string with spaces	tyx@1	inx	lda >Err88Blocks,x	bne @2	lda #' '	sta >Err88Blocks,x	bra @1@2	LongI On	LongA On	rep #$30	sec	; Display the message string	lda #$0088	jsl ErrorErrorExit	pha	jsr DisposeMemory	pla	sec	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .DisposeMemory;; Description:	DisposeMemory is a local subroutine to dispose of all;	the little memory segments created by the NewFile;	subroutine, below.;; Inputs:	none;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Put the contents of DataHandle in a zero page location for later indirect ; access and also push it onto the stack for a _DisposeHandle call.	lda DataHandle	sta <ZPTemp	pha	lda DataHandle+2	sta <ZPTemp+2	pha; Before disposing of the memory segment, get the handle to the next segment; and store it in DataHandle	lda [<ZPTemp]	sta DataHandle	ldy #0002	lda [<ZPTemp],y	sta DataHandle+2; Now we're ready to delete the memory segment	ldx #DisposeHandle	jsl ToolLocator; As long as we get no error, keep deleting	bcc DisposeMemory; We finally got an error!  Must have gotten them all.	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .NewFile;; Description:	NewFile is called when a File Not Found or Path Not Found;	error occurs, indicating that a new file is to be added;	to an existing directory.  It will check the directory to;	see if it will grow a block with the addition of the new;	file.  If it will, it will decrement our FreeSpace value.;;	A little data structure in memory is maintained for each;	directory which contains the handle to the next structure,;	the number of entries and the full pathname of the direc-;	tory.  The format of the structure is:;;	   $00-$03 = Handle to next data structure;	   $04-$05 = Number of entries in this directory;	   $06-    = Full pathname of the directory;	             (GS/OS Class 1 input string);;	Handle to the first data structure is in DataHandle.;	DO NOT forget to _DisposeHandle of all segments when;	finished!;; Inputs:	none (<ZPTemp1 expected to point to destination name);; Outputs:	c-flag clear if no errors occured;	c-flag set & A-reg contains error code if error; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	lda [<ZPTemp1]	; Save LengthWord	sta OriginalLength	; for later restoration	lda <ZPTemp1+2	; ...and pointer	sta TempPointer+2	lda <ZPTemp1	sta TempPointer	stz StackCounter	; Initialize stack counter; Drop the last name off of the destination name and our full pathname to; create the pathname for the directory.DropName	lda [ZPTemp1]	tay	; Back up to previous slash	iny	sep #$0020	LongA Off@1	lda [<ZPTemp1],y	cmp #SeparatorChar	beq DropDone	dey	bne @1; If we fell through to here, we're dealing with a partial pathname from the; Standard Update SuperScript that lacks a volume name.  We can safely; assume that the root directory will not grow.  (It's four blocks long to; begin with and will generate a "Directory Full" error if we overflow it.	LongA On	rep #$0020	brl AnyMoreVariables; We've drop the last hierarchical level in the pathname.DropDone	LongA On	rep #$0020	dey	dey	tya	sta [<ZPTemp1]	; New lengthWord of destination name; Check the pathname against all the names we are holding in data structures to; see if we have previously encountered this directory.;       If DataHandle is zero, we have no stored data yet and we know we;       have nothing to search.	lda DataHandle+2	ora DataHandle	beq DoesDirExist	lda DataHandle	ldx DataHandle+2;       We have stored data.  Let <ZPTemp2 point to the 1st pathname.MainSearchLoop	phx	pha	jsl Dereference	; Dereference the handle and...	clc	;  ...set up <ZPTemp2 to point to the	pla	;  pathname in the data structure	adc #$0006	sta <ZPTemp2	pla	adc #$0000	sta <ZPTemp2+2;       Compare name in data structure to one we want	lda [<ZPTemp1]	; Name we want to find	cmp [<ZPTemp2]	; Name in current data structure	bne NextSearch	tay	iny	sep #$0020	LongA OffSearchLoop	dey	beq GottaMatch	lda [<ZPTemp1],y	cmp [<ZPTemp2],y	beq SearchLoop	LongA On	rep #$0020NextSearch;       This one didn't match...set up for next one, if there is one.	jsr Point2Beginning	; Re-set <ZPTemp2 to point to beginning	ldy #$0002	;  of the data structure.	lda [<ZPTemp2],y	tax	lda [<ZPTemp2]	bne MainSearchLoop	; If handle is non-null, there's more	cpx #0000	beq DoesDirExist	; No more	bra MainSearchLoopGottaMatch	LongA On	rep #$0020	lda TempPointer	; Restore original pointer, if changed	sta <ZPTemp1	lda TempPointer+2	sta <ZPTemp1+2	lda OriginalLength	;  ...and length word	sta [<ZPTemp1];       Re-set <ZPTemp2 to point to the beginning of the data structure.	jsr Point2Beginning	brl IncrementCnt	; No we haven't encountered this directory before.  See if it exists.DoesDirExist	lda <ZPTemp1	sta GetInfoPath	lda <ZPTemp1+2	sta GetInfoPath+2	jsl GSOS	dc.w Get_File_Info	dc.l GetInfoParms	bcc PathnameExists		cmp #FileNotFound	beq FileDoesntExist	cmp #PathNotFound	beq FileDoesntExist		jsl Error	brl NewFileErrExit; The pathname does not exit.  Store the length word on the stack and; start all over again.FileDoesntExist	lda [<ZPTemp1]	; Save current length word	pha	lda <ZPTemp1+2	; Save current pointer	pha	lda <ZPTemp1	pha	inc StackCounter	brl DropName; The pathname exists.  Build it's data structurePathnameExists;       Get a block of memory large enough to hold pathname + 9 bytes;       (LengthWord, LongWord Handle, Word FileCount, trailing null added;       by the GStr routines.)	pha	; Space for result	pha	clc	; Calculate memory block size needed	lda [<ZPTemp1]	; Get the LengthWord	adc #0009	;  and add on 9 bytes	tax	lda #0000	adc #0000	pha	; Size of block to create	phx		lda >MyID	; ID of program owning the block	pha	pea %0000000000010000 ; Attributes	pea 0000	; Push location needed	pea 0000	ldx #NewHandle	jsl ToolLocator	bcc @MemoryOK	pla	; Oops, not enought memory	pla	lda #$008B	jsl Error	brl NewFileErrExit@MemoryOK;       If DataHandle is zero, we have no stored data yet so store the;       data handle in "DataHandle".	lda DataHandle+2	ora DataHandle	bne @1	pla	sta DataHandle	; Store the handle is "DataHandle"	tax	pla	sta DataHandle+2	bra @2;       There is previous data stored, so store the handle to the new;       memory segment in the previous data structure.@1	pla	sta [<ZPTemp2]	; Store the handle in last data structure	tax	ldy #0002	pla	sta [<ZPTemp2],y;       Get the pointer to the pathname into <ZPTemp2@2	pha	phx	jsl Dereference	clc	pla	adc #0006	sta <ZPTemp2	pla	adc #0000	sta <ZPTemp2+2;       Store the full pathname	pei <ZPTemp1+2	pei <ZPTemp1	pei <ZPTemp2+2	pei <ZPTemp2	jsl C1InpToC1Inp;       Set <ZPTemp2 to point to the beginning of the memory block	jsr Point2Beginning;       Be sure the Handle to the next data structure and the File Count;       word is initially zero	lda #0000	ldy #0004@0	sta [<ZPTemp2],y	dey	dey	bpl @0;       OPEN the directory.  If we get a "Path Not Found" error, we know;       it does not exist and we'll be adding the first file.	lda <ZPTemp1	sta OpenPath	lda <ZPTemp1+2	sta OpenPath+2	jsl GS