the old.** Inputs:	none** Outputs:	c-flag set if error** External Refs:	Import Allocate	Import Dereference	Import Error	Import NextFileSpec** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *OurMarkLoc	equ SourceSizeOurMark	equ $FFFF; If we're REMOVEing, there is nothing to do.	bit RemoveFlag	bpl @1	brl SortEnd@1; get scriptÕs size worth of space to move it into	pha	; Get the script's size	pha	pei <ScriptHdl+2	pei <ScriptHdl	ldx #GetHandleSize	jsl ToolLocator	pla	; low word: this is it	plx	;  (throw away high word)	sta ScriptLen	; calculate length of script	jsl Allocate	; get memory block the length of script (in A)	bcc @ok2	brl SortEnd	; if not enough memory, then stick with orig script@ok2	sty NewScriptHandle+2 ; store for disposeHandle later	stx NewScriptHandle	phy	; Handle for _HLock	phx	phy	; Handle for Dereference	phx	ldx #HLock	jsl ToolLocator	jsl Dereference	plx	ply	stx <ZPTemp2	; dest loc for next filespec	stx NewScriptPtr	sty <ZPTemp2+2	sty NewScriptPtr+2; Initialize everything	lda <ScriptPtr	; Put the script pointer in ZPTemp	sta <ZPTemp	; scouting location: looking for section to move	lda <ScriptPtr+2	sta <ZPTemp+2; First move the delete filespecs; theyÕll all end up at the beginning of the new script; (theyÕre probably already there, except possibly in the case of the Easy Update script).	stz NotYetMovedSet	; NotYetMoved location not yet valid@Again	lda [<ZPTemp]	; Get the FlagsWord of this FileSpec	and #Flag3	beq @NoCopy	; If hi-bit clr, bra: not a delete, so no copy	jsr CopyFileSpec	;  else copy filespec at ZPTemp into ZPTemp2	bra @MoveOn@NoCopy	lda NotYetMovedSet	bne @MoveOn	; bra if itÕs already been set	inc NotYetMovedSet	; else set flag and	lda <ZPTemp	;  set NotYetMoved	sta NotYetMoved	;  (this is the 1st filespec not copied)	lda <ZPTemp+2	sta NotYetMoved+2@MoveOn	jsr NextFileSpec	; advance ZPTemp to next filespec	bcc @Again	; loop until reach end