ec	jsr CopyFileSpec	; copy filespec at ZPTemp into ZPTemp2 & mark it;  advance ZPTemp (ignore delete-only);    copy and mark each matching filespec@FindNext	jsr NextFileSpec	; advance ZPTemp to next filespec	bcs HitEndOfScript	; bra if no more filespecs (end of script)	lda [<ZPTemp]	; Get the FlagsWord	and #Flag3	bne @FindNext	; bra if hi-bit set: deletion, so get another	jsr CompareSrcePfx	; same source prefix as SourceToSortOn?	beq InnerLoop	; loop back if prefix matches SourceToSortOn;    if not match, then if NotYetMoved is not set, then set it	lda NotYetMovedSet	bne @FindNext	; bra if itÕs already been set	inc NotYetMovedSet	; else set flag and	lda <ZPTemp	;  set NotYetMoved	sta NotYetMoved	;  (this is the 1st filespec not yet copied)	lda <ZPTemp+2	sta NotYetMoved+2	bra @FindNext	; bra to get next filespec; ZPTemp is on the second FieldSeparator (~), indicating end-of-ScriptHitEndOfScript;  if end of script,;    if NotYetMoved is not set, then weÕre done (all the filespecs matched)	lda NotYetMovedSet	beq DoneSorting;    else bra to OuterLoop	bra OuterLoop; Script is now sorted at NewScriptPtr:; move sorted compacted script back to ScriptPtr & release NewScriptPtr memory; (if Standard Update, a resource handle points at ScriptPtrÕs memory, but if;  Customized Install, something else points here, ;  so we canÕt just release ScriptPtr to use NewScriptPtr, but must stick with ScriptPtr.)DoneSorting	lda NewScriptPtr+2	; source	pha	lda NewScriptPtr	pha	pei <ScriptPtr+2	; dest	pei <ScriptPtr	pea 0	; size	lda ScriptLen	dec a	; didnÕt move second tilde	pha	ldx #BlockMove	; move the script back to ScriptPtr	jsl ToolLocator	clc	; clear carry: ok; release NewScriptPtr memoryCleanUp	php	; save carry (ok / not ok)	lda NewScriptHandle+2	pha	lda NewScriptHandle	pha	ldx #DisposeHandle	jsl ToolLocator	plp	; restore carry (ok / not ok)	rtsSortEnd	clc	rtsSortErrEnd	sec	; set carry: error	bra CleanUpNewScriptHandle	ds.l 1NewScriptPtr	ds.l 1NotYetMoved	ds.l 1	; lowest original-script byte not yet movedNotYetMovedSet	ds.w 1	; true=NotYetMoved is valid for this passScriptLen	ds.w 1SourceToSortOn	ds.b MaxPrefixLen+2	; HFS max (27) + leading/trailing colons	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetCopyingFileSpec;; Description:	Advance, if necessary, to a FileSpec that copies a file ;	(one with a source prefix), ;	using ZPTemp to point at each FileSpec.;	Ignore any FileSpecs that have been marked.;	Ignore delete-only (no source prefix);;	Note: does not advance if the current FileSpec qualifies.;; Inputs:	none;; Outputs:	c-flag set if we have reached the end of the script; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; If the FlagWord has Flag3 set, we're just going to delete the destination; file, if it exists, and there is no source pathname.GetNextLoop	lda [<ZPTemp]	; Get the FlagsWord	and #Flag3	bne @Next	; If hi-bit set: deletion, so go on; so this is a filespec that copies a file (one with a source prefix); If it is marked, ignore it anyway	ldy #OurMarkLoc	; temporarily used as a marker to indicate	lda [<ZPTemp],y	;   file has already been moved	cmp #OurMark	bne @GotOne	; bra if weÕre done (not previously marked); previously marked; go on to the next@Next	jsr NextFileSpec	; advance ZPTemp to next filespec	bcc GetNextLoop	; bra if not at end of script	rts@GotOne	clc	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CompareSrcePfx;; Description:	Compare source prefix in FileScript pointed to by ZPTemp ;	to SourceToSortOn.;; Inputs:	none;; Outputs:	z-flag set if they match (caller can beq); . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .		ldx #0	ldy #Pathnames+2	; past pathname length (we need prefix length)@CmpPrefix	lda [<ZPTemp],y	; get a word of the prefix	cmp SourceToSortOn,x	bne @CmpExit	and #$FF00	; check second byte	c