e a subdirectory and try again;       We're going to keep backing up until we can create a directory;       or we get an error.  BUT! We're going to keep adding stuff to;       the stack as we go.  SO, we need to store the stack pointer here;       so that if we have to bail out before we have unwound the stack,;       we can set it back to where it was.SaveStack	tsc	sta TempCreateDir	lda OpenDPath	; Drop last name by changing length	sta <ZPTemp1	lda OpenDPath+2	sta <ZPTemp1+2	lda [<ZPTemp1]	tay	sep #$0020	LongA Off	sty OriginalLengthNameCutLoop	lda [<ZPTemp1],y	cmp #SeparatorChar	beq FoundSlash	dey	bne NameCutLoopFoundSlash	dey	LongA On	rep #$0020	tya	; Store the new length word	sta [<ZPTemp1];       We have now dropped off the last name, so try creating this directory	lda <ZPTemp1	sta CreatePath	lda <ZPTemp1+2	sta CreatePath+2CreateCall	jsl GSOS	dc.w Create	dc.l CreateParms	bcc DirCreated	cmp #PathNotFound	; If it's not a 'Path not found', oops!	beq @1	ldx CreatePath	ldy CreatePath+2	jsl Error	bcc CreateCall	tax	; Preserve the error code	lda Temp	; Restore the stack	tcs	txa	; Restore the error code	brl CopyExit;       We couldn't create the directory, so save length and back up again@1	lda [<ZPTemp1]	; Get length word	pha	;   and save it	lda OriginalLength	; Get "OriginalLength"	pha	;   and save it too	inc StackDepth		brl CreateDir	; Keep trying;       We created the directory sucessfully.  Check to see if we need to;       create any more.DirCreated	lda StackDepth	; Is there more on the stack?	beq CreateDest	; No, CREATE, OPEN,	and WRITE the file	pla	; Yeah, restore previous stuff and go back	sta OriginalLength	;   and CREATE another directory	pla	sta [<ZPTemp1]	dec StackDepth	bra CreateCallCreateDest	lda OriginalLength	; Restore the original length word	sta [<ZPTemp1]	brl CreateDFile; If we got an error, deallocate memory	and drop through to	CopyExitCopyExit	php	pha	lda Fi