nished; Write out the "chunk" of data.@WriteData	lda ReadDTrnCnt	sta WriteDReqCnt	lda ReadDTrnCnt+2	sta WriteDReqCnt+2@WriteData1	jsl GSOS	dc.w Write	dc.l WriteDParms	bcc @ReadData	ldx OpenDPath	ldy OpenDPath+2	jsl Error	bcc @WriteData1	brl @Finished; Close the source and destination data forks@CloseData	jsl GSOS	; (Source prefix already set)	dc.w Close	dc.l CloseSDParms	bcc @CloseData1	ldx OpenSPath	ldy OpenSPath+2	jsl Error	bcc @CloseData	brl @Finished@CloseData1	jsl GSOS	dc.w Close	dc.l CloseDDParms	bcc @CheckForResources	ldx OpenDPath	ldy OpenDPath+2	jsl Error	bcc @CloseData1	brl @Finished; Check for resources@CheckForResources	lda OpenSDStoreType	; Determine if there are any resouces	cmp #ExtendedType	beq @OpenResources	lda #0000	; Indicate no errors	clc	brl @Finished; Open the source and destination resource forks@OpenResources	jsl GSOS	dc.w Open	dc.l OpenSRParms	bcc @OpenResources1	ldx OpenSPath	ldy OpenSPath+2	jsl Error	bcc @OpenResources	brl @Finished@OpenResources1	jsl GSOS	dc.w Open	dc.l OpenDRParms	bcc @DoResources	ldx OpenDPath	ldy OpenDPath+2	jsl Error	bcc @OpenResources1	brl @Finished; Read a "chunk" of the resource fork@DoResources	lda ReadDBuffer	sta ReadRBuffer	lda ReadDBuffer+2	sta ReadRBuffer+2	lda WriteDBuffer	sta WriteRBuffer	lda WriteDBuffer+2	sta WriteRBuffer+2	lda CopyBufferSize	sta ReadRReqCnt	lda CopyBufferSize+2	sta ReadRReqCnt+2	lda OpenSRRefNum	sta ReadRRefNum	sta CloseSRRefNum	lda OpenDRRefNum	sta WriteRRefNum	sta CloseDRRefNum@ReadResources	jsl GSOS	dc.w Read	dc.l ReadRParms	bcc @WriteResources	cmp #EndOfFile	beq @CloseResources	ldx OpenSPath	ldy OpenSPath+2	jsl Error	bcc @ReadResources	brl @Finished; Write the "chunk" of resources@WriteResources	lda ReadRTrnCnt	sta WriteRReqCnt	lda ReadRTrnCnt+2	sta WriteRReqCnt+2@WriteResources1	jsl GSOS	dc.w Write	dc.l WriteRParms	bcc @ReadResources	ldx OpenDPath	ldy OpenDPath+2	jsl Error	bcc @WriteResources1	brl @Finished; Close the source and destination resource forks@CloseResources	jsl GSOS	;;; (Source prefix already set)	dc.w Close	dc.l CloseSRParms	bcc @CloseResources1	ldx OpenSPath	ldy OpenSPath+2	jsl Error	bcc @CloseResources	brl @Finished@CloseResources1	jsl GSOS	dc.w Close	dc.l CloseDRParms	bcc @Finished	ldx OpenDPath	ldy OpenDPath+2	jsl Error	bcc @CloseResources1	brl @Finished@Finished	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CompareNames;;Description:	This is a local subroutine to compare the full source and;	destination pathnames.  They are already fully expanded;	unless we're running the Standard Update script!  In that;	case, only the source pathname is fully expanded.;; Inputs:	none (It will get the names from the proper places in the;	current FileSpec field.);; Outputs:	c-flag clear if names are identical.;	c-flag set if names are different.;; NOTES:          ¥ <ZPTemp points to the beginning of the current FileSpecField.;                 ¥ Pathnames is the offset to the source pathname, a GSOS;	class 1 input string.  The destination pathname follows;	the source pathname.;                 ¥ <ZPTemp1 is setup to point to the source pathname.;                 ¥ <ZPtemp2 is setup to point to the destination pathname.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Set up the source pathname pointer.  This is also a good chance to put; the pointers into the appropriate OPEN parameter tables.	clc	lda <ZPtemp	adc #Pathnames	sta <ZPTemp1	sta OpenSDPath	sta OpenSRPath	lda <ZPTemp+2	adc #0000	sta <ZPTemp1+2	sta OpenSDPath+2	sta OpenSRPath+2;       Set up the destination pathname pointer.  This is also a good chance;       to put the pointers into the appropriate OPEN parameter tables.	clc	; Calculate location of dest pathname	lda [<ZPtemp1]	; length of source pathname string	adc #0002	; Add on lengthWord	adc <ZPtemp1	; + loc of str yields loc just past source path str	sta <ZPTemp2	;   (yields loc of unexpanded dest path str)	sta OpenDDPath	sta OpenDRPath	sta ExpandInputPath	lda #0000	adc <ZPTemp1+2	sta <ZPTemp2+2	sta OpenDDPath+2	sta OpenDRPath+2	sta ExpandInputPath+2; If the Standard Update script is executing, we don't have a full destination; pathname.	lda >UpdateFlag	and #%0100000000000000	beq DoCompare;       The Standard Update script IS running.  We do not have a full pathname.;       We'll need to get some memory and build a full pathname for comparing.;       ZPTemp2, set earlier, is not valid (points to partial pathname only)	jsl GetCurDirPtr	pha	; Room for result	pha	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer	plx	stx <ZPTemp2	stx ExpandOutputPath	ply	sty <ZPTemp2+2	sty ExpandOutputPath+2	bcc @ExpandDestPath	lda #$0081	; Oops!  Out of memory.	jsl Error		bra Different1@ExpandDestPath	jsl GSOS	dc.w Expand_Path	dc.l ExpandPathParms	pha	; If it didn't fit, resize the buffer	pha	;   and try again.	pei <ZPTemp2+2	; address of buffer	pei <ZPTemp2	jsl GStrResize	sta temp	; remember error code	pla	; pull new address of buffer	sta <ZPTemp2	sta ExpandOutputPath	pla	sta <ZPTemp2+2	sta ExpandOutputPath+2	bcc @AdjustPointer	; bra if no error	lda temp	; get error code	cmp #0004	; GStrBufferError ?	beq @ExpandDestPath	; wasnÕt big enough 1st time; now is; retry@AdjustPointer	inc <ZPTemp2	; Adjust pointer to point at lengthWord	bne @NoAdjustHi	inc <ZPTemp2+2@NoAdjustHi	inc <ZPTemp2	bne @NoAdjustHi2	inc <ZPTemp2+2@NoAdjustHi2; Compare the two strings, byte for byteDoCompare	lda [<ZPTemp1]	; Use source's length word	cmp [<ZPTemp2]	; But first, be sure theyÕre the same	bne Different1	tay	iny	sep #$0020	LongA OffCompareLoop	lda [<ZPTemp1],y	jsl UpperCase8bit	; (Comparison must be case insensitive)	sta temp	lda [<Z