	sbc [<ZPTemp],Y	bcs NoErrorExit; Unlock the file.  (If it's already unlocked, it won't hurt.)UnlockFile	lda #%0000000011100011	sta GetInfoAccess	jsl GSOS	dc.w Set_File_Info	dc.l GetInfoParms	cmp #VolumeNotFound	bne DestroyFile	ldx GetInfoPath	ldy GetInfoPath+2	jsl Error	bcc UnlockFile	bra Exit; Delete the fileDestroyFile	jsl GSOS	; Delete the file	dc.w Destroy	dc.l DestroyParms	bcc Exit;       Some possible returned errors can be ignored.	cmp #PathNotFound	beq NoErrorExit	cmp #FileNotFound	beq NoErrorExit	cmp #invalidAccess	; network error, or folder still has stuff in it	beq NoErrorExitErrorExit	secErrExit	jsl Error	; Report the error	rtsNoErrorExit	clcExit	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .;; Local DataTemp	ds.w 1FreeMemory	ds.l 1CopyBufferSize	ds.l 1TooSmallFlag	ds.w 1OurFlagsWord	ds.w 1FileHandle	ds.l 1	; Handle to file copy bufferBootCodeBuffer	ds.l 1OriginalLength	ds.w 1	; Original name length wordStackDepth	ds.w 1	; Depth of variables on stackDestroyParms	dc.w 0001	; pCountDestroyPath	ds.l 1	; pathnameSysPrefParms	dc.w 0001	; pCount	dc.w 0000	; preferencesPreferences	dc.w 0000NumOfItems	ds.w 1DWriteParms	dc.w 0006	; pCountDWriteDevNum	ds.w 1	; devNumDWriteBuffer	ds.l 1	; buffer	dc.l 00001024	; requestCount	dc.l 00000000	; startingBlock	dc.w 0512	; blockSize	ds.l 1	; transferCount; Parameters for creating subdirectories.CreateParms	dc.w 0007	; pCountCreatePath	ds.l 1	; Pathname pointer	dc.w %11100011	; Access	dc.w $000F	; File type	dc.l $00000000	; Aux type	dc.w $000D	; Storage type	ds.w 1	; Creation date	ds.w 1	; Creation time; Parameters for creating the destination file directory entry.CreateDParms	dc.w 0007	; PCountCreateDPath	ds.l 1	; Pathname	dc.w 0000	; Access	dc.w 0000	; File_Type	dc.l 00000000	; Aux_TypeCreateDStoreType	dc.w 0000	; Storage_Type	dc.l 00000000	; Data_EOF	dc.l 00000000	; Resource_EOF; Parameters for opening the source file data fork and getting ALL the; information about the file.OpenSDParms 	dc.w 0014	; PCountOpenSDRefNum	ds.w 1	; Ref_NumOpenSDPath	ds.l 1	; Pathname	dc.w RequestRead	; Request_Access	dc.w 0000	; Resource_Number	dc.w 0000	; Access	dc.w 0000	; File_Type	dc.l 00000000	; Aux_TypeOpenSDStoreType	dc.w 0000	; Storage_Type ($05 = extended)	dc.l 00000000,00000000 ; Create_Date_Time	dc.l 00000000,00000000 ; Mod_Date_Time	dc.l 00000000	; Option_ListOpenSDEOF	dc.l 00000000	; EOF	dc.l 00000000	; Blocks_UsedOpenSDResourceEOF	dc.l 00000000	; Resource_EOF; Parameters for opening the source file resource fork.OpenSRParms 	dc.w 0004	; PCountOpenSRRefNum	ds.w 1	; Ref_NumOpenSRPath	ds.l 1	; Pathname	dc.w RequestRead	; Request_Access	dc.w 0001	; Resource_Number; Parameters for opening the destination file data fork.OpenDDParms 	dc.w 0004	; PCountOpenDDRefNum	ds.w 1	; Ref_NumOpenDDPath	ds.l 1	; Pathname	dc.w RequestWrite	; Request_Access	dc.w 0000	; Resource_Number; Parameters for opening the destination file resource fork.OpenDRParms 	dc.w 0004	; PCountOpenDRRefNum	ds.w 1	; Ref_NumOpenDRPath	ds.l 1	; Pathname	dc.w RequestWrite	; Request_Access	dc.w 0001	; Resource_Number; Parameters for reading source file data fork.ReadDParms	dc.w 0004	; PCountReadDRefNum	dc.w 0000	; Ref_NumReadDBuffer	dc.l 00000000	; Data_BufferReadDReqCnt	dc.l 00000000	; Request_CountReadDTrnCnt	dc.l 00000000	; Transfer_Count; Parameters for reading source file resource fork.ReadRParms	dc.w 0004	; PCountReadRRefNum	dc.w 0000	; Ref_NumReadRBuffer	dc.l 00000000	; Data_BufferReadRReqCnt	dc.l 00000000	; Request_CountReadRTrnCnt	dc.l 00000000	; Transfer_Count; Parameters for writing destination file data fork.WriteDParms	dc.w 0004	; PCountWriteDRefNum	dc.w 0000	; Ref_NumWriteDBuffer	dc.l 00000000	; Data_BufferWriteDReqCnt	dc.l 00000000	; Request_Count	dc.l 00000000	; Transfer_Count; Parameters for writing destination file resource fork.