routine to this file;; Description:	Opens the alert window and draws the first msg.;	Pointer to window is left in WindowGrafPort.;; Inputs:	none;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; CurrentPort is maintained.	pha	pha	ldx #GetPort	jsl ToolLocator	; Store the current port on the stack	pha	; Room for result	pha	pea WindowTemplate>>16	pea |WindowTemplate	ldx #NewWindow	jsl ToolLocator	pla	sta WindowGrafPort	pla	sta WindowGrafPort+2; Tell the user how to get out of INSTALL/REMOVE	jsr DrawMessage; Tell the user to hang in there	lda #InstallStandBy	jsr UpdateMsgWindow	ldx #SetPort	jsl ToolLocator	; Restore original port	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .DrawMessage;; Description:	Subroutine to redraw the message explaining how;	to terminate further script processing.  It also;	reframes the thermodial.;; Inputs:	none;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	pha	ldx #GetPort	jsl ToolLocator	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	ldx #SetPort	jsl ToolLocator	pea 0008	; Horizontal position	pea 0009	; Vertical position	ldx #MoveTo	; Position pen	jsl ToolLocator	pea TerminationMsg>>16 ; Re-draw the message	pea |TerminationMsg	ldx #DrawString	jsl ToolLocator;;;	pea DialRect>>16	; Re-frame the thermodial in case;;;	pea |DialRect	;   it got erased during another;;;	ldx #FrameRect	;   message (such as a GS/OS request;;;	jsl ToolLocator	;   to mount a volume).	ldx #SetPort	jsl ToolLocator	rts	; Return to caller	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CloseMsgWindow;; Description:	Closes window whose pointer is in WindowGrafPort;	CurrentPort is maintained.;; Inputs:	none (expects value in WindowGrafPort);; Outputs:	any errors return by tool call; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	ldx #CloseWindow	jsl ToolLocator	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .UpdateMsgWindow;; Description:	Updates the message window by drawing a new message in;	the window.;;	CurrentPort is maintained.;; Inputs:	a-reg contains low word of pointer to msg string;; Outputs:	none;; NOTE:	All strings to be printed this way must be in the same;	bank as "ScriptVer".; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	; Save the input word on stack	pha	; Get the current port	pha	ldx #GetPort	jsl ToolLocator	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	ldx #SetPort	jsl ToolLocator	jsr DrawMessage	; Tell the user how to get out of INSTALLREMOVE	lda 5,s	; Get input word back off stack	pea ScriptVer>>16	; Push high word of pointer to string	pha	; Push low word (passed in a-reg)	jsr EraseMsg	; Clear old msg & position pen	ldx #DrawString	jsl ToolLocator	; Print the string (using pointer on stack)	ldx #SetPort	jsl ToolLocator	; Restore port	pla	; pull input word back off stack.	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CreateDial;; Description:	Creates the custom control and sets the;	TotalBlocksForInstall as the number that is used for;	the dial's maximum value.;;	It also causes the control to be drawn.;; Inputs:	none;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	; Get the current port	pha	ldx #GetPort	jsl ToolLocator	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	ldx #SetPort	jsl ToolLocator	pha	; Room for result	pha	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	pea DialRect>>16	pea |DialRect	lda TotalBlocksForInstall+2 ; max size of dial	pha	lda TotalBlocksForInstall	pha	pea 0001	; type of dial	pea 0000	; starting value	pea 0000	; ignore	pea 0000	; ignore	pea ThermoDialProc>>16 ; dial's definition procdure	pea |ThermoDialProc	pea 0000	pea 0000	pea ThermoDialColor>>16 ; color table ptr	pea |ThermoDialColor	ldx #NewControl	jsl ToolLocator	pla	sta DialHandle	pla	sta DialHandle+2*** added 24-Mar-93 SS -- if no total, hide the thermometer	lda TotalBlocksForInstall	ora TotalBlocksForInstall+2	bne @ok	lda DialHandle+2	pha	lda DialHandle	pha	ldx #HideControl	jsl ToolLocator	@ok*** end 24-Mar-93 SS	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	ldx #Drawcontrols	jsl ToolLocator	stz RunningCount	ldx #SetPort	jsl ToolLocator	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .UpdateMsgWindowRead;; Description:	Displays the name of the file being read and updates;	the progress dial by an amount equal to 1/2 the size;	of the file.;;	Uses the size and name from the FileSpec in the compacted;	script.;; Inputs:	none;; Outputs:	none;; NOTE:	Expects <ZPTemp to point to the current FileSpecField; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	; get the current port	pha	ldx #GetPort	jsl ToolLocator	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	ldx #SetPort	jsl ToolLocator	jsr EraseMsg	; Clear old msg & position pen	ldy #SourceSize	lda [<ZPTemp],y	lsr a	clc	adc RunningCount	sta RunningCount	pea ReadingString>>16	pea |ReadingString	ldx #DrawString	jsl ToolLocator	; Print the string (using pointer on stack)	lda OpenSPath+2	; Print only the filename to prevent	pha	;   overflowing the box.	lda OpenSPath	pha	jsr DrawFilename	jsr DrawMessage	lda RunningCount	pha	lda DialHandle+2	pha	lda DialHandle	pha	ldx #SetCtlValue	jsl ToolLocator	ldx #SetPort	jsl ToolLocator	; restore port	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .UpdateMsgWindowWrite;; Description:	Displays the name of the file being written and updates;	the progress dial by an amount equal to the 1/2 the;	size of the file.;;	Uses the size and name from the FileSpec in the compacted;	script.;; Inputs:	none;; Outputs:	none;; NOTE:	Expects <ZPTemp to point to the surrent FileSpecField; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	; get the current port	pha	ldx #GetPort	jsl ToolLocator	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	ldx #SetPort	jsl ToolLocator	jsr EraseMsg	; Clear old msg & position pen	ldy #SourceSize	lda [<ZPTemp],y	lsr a	bcc @1	; (If the number was odd, we need	inc a	; to make up the extra block here	clc	; so dial will finish at end.)@1	adc RunningCount	sta RunningCount	pea WritingString>>16	pea |WritingString	ldx #DrawString	; Print the string (using pointer on stack)	jsl ToolLocator	lda OpenDPath+2	; Print only the filename to prevent	pha	;   overflowing the box.	lda OpenDPath	pha	jsr DrawFilename	jsr DrawMessage	lda RunningCount	pha	lda DialHandle+2	pha	lda DialHandle	pha	ldx #SetCtlValue	jsl ToolLocator	ldx #SetPort	; restore port	jsl ToolLocator	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .UpdateMsgWindowSkip;; Description:	Displays the name of the file being skipped and updates;	the progress dial by an amount equal to the 1/2 the;	size of the file.;;	Uses the size and name from the FileSpec in the compacted;	script.;; Inputs:	none;; Outputs:	none;; NOTE:	Expects <ZPTemp to point to the surrent FileSpecField; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	; get the current port	pha	ldx #GetPort	jsl ToolLocator	lda WindowGrafPort+2	pha	lda WindowGrafPort	pha	ldx #SetPort	jsl ToolLocator	jsr EraseMsg	; Clear old msg & position pen	ldy #SourceSize	lda [<ZPTemp],y	lsr a	bcc @1	; (If the number was odd, we need	inc a	; to make up the extra block here	clc	; so dial will finish at end.)@1	adc RunningCount	sta RunningCount	pea SkippingString>>16	pea |SkippingString	ldx #DrawString	; Print the string (using pointer on stack)	jsl ToolLocator	lda OpenDPath+2	; Print only the filename to prevent	pha	;   overflowing the box.	lda OpenDPath	pha	jsr DrawFilename	jsr DrawMessage	lda RunningCount	pha	lda DialHandle+2	pha	lda DialHandle	pha	ldx #SetCtlValue	jsl ToolLocator	ldx #SetPort	; restore port	jsl ToolLocator	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .EraseMsg; ; Description:	EraseMsg clears the message portion of the user;	notification window and positions the pen in preparation;	for drawing the next message.;; Inputs:	none;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pea 0008	; Horizontal position	lda MsgRect+4	; Vertical position	dec a	pha	ldx #MoveTo	; Position pen	jsl ToolLocator	pea MsgRect>>16	; Message rectangle	pea |MsgRect	ldx #EraseRect	; Erase rectangle	jsl ToolLocator	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .DrawFilename;; Description:	Draws the filename portion of the specified full pathname.;; Inputs:	Pointer to the full pathname on the stack.;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	phd	tsc	tcd; Find the filename portion of the full pathname GS/OS class 1 input string.	ldx #0000	; Initialize character counter	lda [05]	; Initialize index	tay	iny	sep #$0020	LongA OffSearchLoop	lda [05],y	cmp #SeparatorChar	beq SearchDone	dey	inx	cpy #0001	bne SearchLoopSearchDone; Move the substring into the String Buffer.	stx StringLength	; Length word for comparison	stx StringBuffer	; To become Pascal string length byte	ldx #0000MoveLoop	inx	iny	lda [05],y	sta StringBuffer,x	cpx StringLength	bne MoveLoop; Draw the string.DrawTheString	rep #$0020	LongA On	pea StringBuffer>>16	pea |StringBuffer	ldx #DrawString	jsl ToolLocator	pld	; Restore called d-Page	lda 1,s	; Move the return address up	sta 5,s	pla	; Pull the inputs off the stack	pla	rts	Eject; Stuff associated with the message window that lets user know what's happeningWindowTemplate	dc.w WinTempLen	; paramLength	dc.w %0010000000100000 ; wFrame	dc.l 00000000	; wTitle	dc.l 00000000	; wRefCon	dcb.b 8,0000000000000000 ; wZoom	dc.l 00000000	; wColor	dc.w 0000	; wYOrigin	dc.w 0000	; wXOrigin	dc.w 0000	; wDataH	dc.w 0000	; wDataW	dc.w 0000	; wMaxH	dc.w 0000	; wMaxW	dc.w 0000	; wScrollVer	dc.w 0000	; wScrollHor	dc.w 0000	; wPageVer	dc.w 0000	; wPageHor	dc.l 00000000	; wInforRefCon	dc.w 0000	; wInfoHeight	dc.l 00000000	; wFrameDefProc	dc.l 00000000	; wInfoDefProc	dc.l 00000000	; wContDefProcWindowPosition	dc.w 111,135,151,505 ; wPosition	dc.l $FFFFFFFF	; wPlane	dc.l 00000000	; wStorageWinTempLen	equ *-WindowTemplateMsgTop	equ 15MsgLeft	equ 0MsgBottom	equ MsgTop+12MsgRight	equ 370MsgRect	dc.w MsgTop,MsgLeft,MsgBottom,MsgRight	; Message rectangleWindowGrafPort	ds.l 1DialHandle	dc.l 00000000DialRect	dc.w 30,30,38,335ThermoDialColor	dc.w %0000000000000000 ; bits 0-3: outline color (black)	dc.w %0000000000001111 ; bits 0-3: interior color (white)	dc.w %0000000000000000 ; bits 0-3: foreground color (black)	dc.w %0000000000000001 ; bits 0-3: background color (red)		   ;   bit 15: 1 = dotted, 0 = solidRunningCount	dc.w 0StringLength	ds.w 1StringBuffer	ds.b 33	; Room for 32 character Pascal string	EndP ;{MsgWindow}	Eject;===============================================================;=============== General Install.asm Subroutines ===============;===============================================================* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CheckForInterrupt	Proc** Description:	Calls the event manager and looks for the*	"Apple-Period" command.** Inputs:	c-flag clear = display "Unknown Mix" dialog if*	     Apple-<period> pressed*	c-flag set = don't display "Unknown Mix" dialog** Outputs:	c-flag set = user wants to interrupt, clear if not.** External Refs:	Import ContinueStr	    ; From Data.asm	Import DrawStopIcon	Import EndUnknownMixMsg ; From Data.asm	Import HaltStr	    ; From Data.asm	Import Task:TaskRecord  ; From Data.asm	Import UnknownMixMsg    ; From Data.asm** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	php	; Save c-flag	pha	; Space for result	pea #keyDownMask+autoKeyMask+deskAccMask	pea Task>>16	pea |Task	ldx #GetNextEvent	jsl ToolLocator	pla	; Get the TaskCode	beq @Done	lda >Task.Modifiers	and #AppleKey	beq @Done	lda >Task.Message	and #$00FF	cmp #'.'	bne @Done; There WAS an interrupt request from the user!  If the call was made with; the c-flag clear, we must display the "Unknown Mix" dialog.	plp	bcs @1	ldx #InitCursor	jsl ToolLocator	jsr UnknownMix	; c-flag set on HALT, clear on CONTINUE	php	ldx #WaitCursor	jsl ToolLocator	jsr DrawMessage	plp@1	rts@Done	plp	clc	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .UnknownMix;; Description:	UnknownMix - This routine will present a dialog box;	notifying the user that an unknown mix of files may;	be present on the destination disk if they stop the;	current process.  It should be called when;	Open-Apple-<period> is pressed.;; Inputs:	none;; Outputs:	c-flag set = "Halt" was selected;	c-flag clear = "Continue" was selected;; External references:	import DialogFlag	import UpdateMainDialog	import UpdateEasyDialog;; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	; Space for result	pea UnknownMixTemplate>>16 ; Pointer to template	pea |UnknownMixTemplate	pea 0000	; Filter procedure	pea 0000	ldx #Alert	jsl ToolLocator	pla	; Get the item hit ID	cmp #0002	; Clear the c-flag if "Continue" was hit	php	; Set the c-flag if "Halt" was hit; update window	lda >DialogFlag	bmi @doEasy	; bra if Easy Update	jsl UpdateMainDialog ; update	bra @unknownDone@doEasy	jsl UpdateEasyDialog ; update	@unknownDone	plp	rts; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Dialog template: installation only partially complete: unknown mix of files installeduWidth    equ 377uHeight   equ 62uTop      equ (200/2)-(uHeight/2)-8uLeft     equ (640/2)-(uWidth/2)uBottom   equ uTop+uHeightuRight    equ uLeft+uWidthUnknownMixTemplate	dc.w uTop,uLeft,uBottom,uRight	dc.w 5555	; ID	dc.b $81	dc.b $81	dc.b $81	dc.b $81	dc.l ContinueButton	dc.l HaltButton	dc.l MessageItem	dc.l Icon	dc.l 00000000ContinueButton	dc.w 1	; ID	dc.w uHeight-20,uWidth-112  ; Bounds rect for button	dc.w uHeight-8,uWidth-22	dc.w ButtonItem	; Type	dc.l ContinueStr	; Item descriptor	dc.w 0000	; Item value	dc.w 0001	; Item flag	dc.l 00000000	; Item colorHaltButton	dc.w 2	; ID	dc.w uHeight-20,uWidth-224  ; Bounds rect for button	dc.w uHeight-8,uWidth-134	dc.w ButtonItem	; Type	dc.l HaltStr	; Item descriptor	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorMessageItem	dc.w 3333	; ID	dc.w 7,83,uHeight-28,uWidth-16  ; Bounds rect for text	dc.w LongStatText2+ItemDisable ; Type	dc.l UnknownMixMsg  ; Item descriptor	dc.w EndUnknownMixMsg-UnknownMixMsg ; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorIcon	dc.w 0004	; ItemID	dc.w 8,18,28,76	; ItemRect	dc.w UserItem+ItemDisable ; ItemType	dc.l DrawStopIcon	; ItemDescr	dc.w 0000	; ItemValue	dc.w 0000	; ItemFlag	dc.l 00000000	; ItemColor	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *GetScriptMem	Proc** Description:	Allocates memory of the specified size, locks it,*	dereferences it, and returns the pointer.** Inputs:	A-reg contains size of memory segment to create.** Outputs:	X and Y contain pointer to the segment.*	cFlag Clear: no errors*	cFlag Set: error!  Error code in A-reg.** External Refs:	Import Allocate	; From MainSub	Import Dereference	; From MainSub** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	jsl Allocate	; (A-reg contains size)	bcs GetScriptExit	phy	; Handle for _HLock	phx	phy	; Handle for Dereference	phx	ldx #HLock	jsl ToolLocator	jsl Dereference	plx	plyGetScriptExit	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DeleteField1	Proc*	Entry DeleteField** Description:	DeleteField1 will search for the next FieldSeparator*	character and delete the current field. DeleteField assumes that*	<ZPTemp points to the beginning of the field and that the*	Y-reg is pointing at the next FieldSeperator character.*	If it is not, make the call to DeleteField1, which will*	adjust Y to point to the next FieldSeparator character.** Inputs:	none  (For "DeleteField" entry point, Y-reg must have been set.)** Outputs:	cFlag Clear: there are more fields following*	cFlag Set: there are no more fields following** External Refs:	Import FindSeparator	Import ReadBufEnd** Side Effects:	A field is deleted by moving the remainder of the script*	down in memory, over-writing the field to be deleted.*	Note that the memory is NOT resized at this point.** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; If the Y-reg is not already pointing at the next FieldSeparator character,; we have to take care of that first.	jsr FindSeparator; We want to delete	the field to the left of the Y index.  <ZPTemp points to the; location we want to move things down to and <ZPTemp+Y points to the location; we want to move things down from.  GetEOFEOF-Y is the number of bytes to move.; (Update GetEOFEOF	to represent the number of bytes moved so it is ready for; the next loop.)DeleteField	sty Temp	clc	; Calculate location of start of bytes	tya	;  to be copied.	adc <ZPTemp	tax	lda #0000	adc <ZPTemp+2	pha	; PushLong source	phx	pei <ZPTemp+2	; PushLong destination	pei <ZPTemp	sec	; Calculate number of bytes to move	lda ReadBufEnd	sbc <ZPTemp	tax	lda ReadBufEnd+2	sbc <ZPTemp+2	tay	sec	txa	sbc Temp	; (Temp = Y index)	tax	tya	sbc #0	pha	; PushLong count	phx	ldx #BlockMove	; Move the stuff down	jsl ToolLocator; Be sure that there is another field left.	lda [<ZPTemp]	; A field beginning with the	and #$00FF	cmp #FieldSeparator	;  FieldSeperator char = end of script	bne @1	sec	; No more fields left	rts@1	clc	; More fields left	rtsTemp	ds.w 1	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *FindSeparator	Proc	; rdl-reviewed** Description:	FindSeparator will position Y at the beginning of the*	next FileSpecField.** Inputs:	none  (value passed in Y is ignored)*	(ZPTemp points to current field.)** Outputs:	Y-reg contains position of next field separator.*	cFlag Clear: no errors*	cFlag Set: No-end-of-script error** External Refs:	Import Error	; From MainSub.asm** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	ldy #Pathnames	; Index is offset to pathnames	lda [<ZPTemp],y	; Get the Source pathname lengthWord	clc	; Add on the offset to the pathnames	adc #Pathnames+2	;  plus two for the length word	tay	; Use as index to destination pathname	clc	adc [<ZPTemp],y	; Get the Destination pathname lengthWord	tay	iny	; Add two more for length word	iny	lda [<ZPTemp],y	; Be certain that there is a separator	and #$00FF	; (Mask off extra byte.)	iny	cmp #FieldSeparator	beq Exit; Report errors.Oops	lda #$0085	; Notifiy user there is no end-of-FileSpec	jsl Error	;  mark!	sec	rtsExit	clc	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *NextFileSpec	Proc** Description:	NextFileSpec will update the value in <ZPTemp to point*	to the next FileSpec field in the compacted script held*	in memory.** Inputs:	Y-reg is ignored** Outputs:	c-flag clear if there is another FileSpec field*	c-flag set if we have reached the end of the script** External Refs:	Import FindSeparator** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	jsr FindSeparator	; Find the next FieldSeparator	clc	; Update <ZPTemp	tya	adc <ZPTemp	sta <ZPTemp	lda #0000	adc <ZPTemp+2	sta <ZPTemp+2	lda [<ZPTemp]	; Check to see if it is a null field	and #$00FF	; Mask off extra character	cmp #FieldSeparator	bne NotNull	sec	; Set c-flag!  It's a null field! End of script!	rts;NotNull	clc	; Clear c-flag.  There's another field.	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *ConvertDateTime	Proc** Description:	Converts date and time returned by GS/OS into the*	old ProDOS format.** Inputs:	none  (Get values from GetInfoCreation)** Outputs:	none  (Stores values in GetInfoDate1 and GetInfoTime1.)** External Refs:	Import GetInfoCreation	Import GetInfoDate1	Import GetInfoTime1** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda GetInfoCreation+4 ; Get Month/Day	and #$00FF	; Mask off month	inc a	; (Day returned as 0-30 not 1-31!)	sta GetInfoDate1	;save the day in prodos format	lda GetInfoCreation+5 ; Get Null/Month	and #$00FF	; Mask off null	inc a	; (Month returned as 0-11 not 1-12!)	asl a	asl a	asl a	asl a	asl a	;shift to correct position	ora GetInfoDate1	;month is now happy	sta GetInfoDate1	lda GetInfoCreation+3 ; Get Day/Year	and #$00FF	; Mask off day	xba	asl a	;shift year to upper 7 bits	ora GetInfoDate1	sta GetInfoDate1	lda GetInfoCreation+1 ; Get Hour/Minutes	and #$00FF	; Mask off hour	sta GetInfoTime1	lda GetInfoCreation+2 ; Get Year/Hour	and #$00FF	; Mask off year	xba	ora GetInfoTime1	sta GetInfoTime1	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *ResizeScriptMemory	ProcName** Description:	Resizes the memory used by the SuperScript, dereferences*	the handle into "ScriptPtr" and returns with the memory*	locked.** Inputs:	X and Y contain new size** Outputs:	cFlag clear: no errors*	cFlag set: memory manager error in A-reg** External Refs:	Import Error	; From MainSub.asm** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	stx NewSize	sty NewSize+2	ldy #4	; Unlock the handle	lda [<ScriptHdl],y	and #$FFFF-attrLocked	sta [<ScriptHdl],y	ldy NewSize+2	phy	ldx NewSize	phx	pei <ScriptHdl+2	; Resize the memory	pei <ScriptHdl	ldx #SetHandleSize	jsl ToolLocator	bcc MemoryOK	lda #$0084	jsl Error	bra ExitMemoryOK	ldy #4	; Lock the handle	lda [<ScriptHdl],y	ora #attrLocked	sta [<ScriptHdl],y	lda [<ScriptHdl]	; Dereference the handle	sta <ScriptPtr	ldy #0002	lda [<ScriptHdl],y	sta <ScriptPtr+2Exit	rtsNewSize	ds.l 1	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DoneMessage	Proc** Description:	Displays the message letting the user know that script*	execution has been completed.** Inputs:	none** Outputs:	none** External Refs:	Import EndInstallDoneMsg ; From Data.asm	Import EndRemoveDoneMsg  ; From Data.asm	Import InstallDoneMsg    ; From Data.asm	Import OKStr	     ; From Data.asm	Import RemoveDoneMsg     ; From Data.asm** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	bit RemoveFlag	bpl @Install	lda #RemoveDoneMsg	sta MessageStr	lda #^RemoveDoneMsg	sta MessageStr+2	lda #EndRemoveDoneMsg-RemoveDoneMsg	sta MessageLength	bra @DoIt@Install	lda #InstallDoneMsg	sta MessageStr	lda #^InstallDoneMsg	sta MessageStr+2	lda #EndInstallDoneMsg-InstallDoneMsg	sta MessageLength@DoIt	ldx #InitCursor	jsl ToolLocator	pea doneBeep	; beep when Alert is drawn	ldx #SysBeep2	jsl ToolLocator	pha	   ; Room for result	pea AlertTemplate>>16 ; Pointer to alert template	pea |AlertTemplate	pea 0000	   ; Pointer to filter proc. (none)	pea 0000	ldx #Alert	jsl ToolLocator	pla	   ; Discard result	rts	Eject; This is the AlertTemplate for the dialog to notify the user that the; Installation or Removal is complete.AlertTemplate@Width    equ 300		; Local equates for the alert template@Height   equ 47@BtnWidth equ 80@Top      equ (200/2)-(@Height/2)@Left     equ (640/2)-(@Width/2)@Bottom   equ @Top+@Height@Right    equ @Left+@Width	dc.w @Top,@Left,@Bottom,@Right	dc.w $6789	 ; AlertID	dc.b $80,$80,$80,$80 ; Stage1, Stage2, Stage3, Stage4	dc.l @FirstItem	 ; First item template	dc.l @SecondItem	 ; Second item template	dc.l 00000000; OK Button@FirstItem	dc.w 0001		; ItemID 	dc.w @Height-18,@Width/2-(@BtnWidth/2)	; ItemRect	dc.w @Height-6,@Width/2+(@BtnWidth/2)	dc.w ButtonItem		; ItemType	dc.l OKStr		; ItemDescr	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColor; text@SecondItem	dc.w 0002		; ItemID	dc.w 4,20,@Height-20,@Width-20	; ItemRect	dc.w LongStatText2+ItemDisable	; ItemTypeMessageStr	dc.l 00000000		; ItemDescrMessageLength	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColor	EndP	End